/* 原创白话入口。每行作者数据转为同一图解 schema；原课程例题与自测保留。 */
(() => {
  const data = {};
  const put = (id, plainTitle, goal, story, terms, kind, nodes, caption, steps, boundary) => { data[id] = {plainTitle, goal, story, terms: terms.map(([word,meaning,example])=>({word,meaning,example})), diagram:{kind,nodes:nodes.map(([name,detail])=>({name,detail})),caption},steps:steps.map(([title,text])=>({title,text})),boundary}; };
  put('prob-experiment','抽球之前，哪些规则必须先讲清？','先确定一次实验到底做什么，再讨论结果机会。',
    '袋中有两只红球、一只白球，连续抽两次。第一次抽完是否放回，会改变第二次的机会；只记录颜色，还是给三只球分别编号，也会改变结果清单。随机不是没有规则，而是规则说清后，仍不知道这次会落在哪个结果上。先把抽法和记录方法画出来，概率才有地方安放。',
    [['随机试验','规则确定、单次结果事前仍不能确定的操作。','按规定抽两次球。'],['结果','按预先约定实际记录下来的那一次情况。','先红后白是一种颜色记录。'],['模型','把实际问题简化成可分析规则的说明。','本例约定每个球被抽中机会相同。']],
    'compare',[['先定操作','抽两次，是否放回？'],['再定记录','记颜色还是球编号？'],['最后给机会','按规则分配概率']],
    '三项是建模要分别确定的内容，不是“没说清规则也能先算”的计算流水线。',
    [['操作改变，机会就变','第一次抽到红球后，若放回，袋子仍是两红一白；若不放回，就只剩一红一白。不要因为都叫“抽球”，就把后一次机会看成相同。'],['记录改变，结果卡也变','把球编成红甲、红乙、白丙，能区别是哪只红球；只记颜色会把某些编号结果合并。合并后的颜色记录不一定仍然等可能，需要重新计算。'],['先写假设，再信数字','“每只球等可能”是本例模型的约定，不是从“袋里有三只球”自动推出。若抽取装置偏向某只球，就应改变模型，而不是强迫事实服从三等份。']],
    '图示只讨论抽取规则与记录方式；真实抽取是否等可能，需要装置或数据支持，不能只凭结果有限来断言。');
  put('prob-events','一次结果和“满足条件的一堆结果”有何不同？','能用结果卡片区分样本空间与事件。',
    '掷一次普通六面骰，最终只出现一个点数。把六种可能各写在一张卡上，就得到这次实验的完整清单。你关心“点数为偶数”，相当于从清单中圈出 2、4、6 三张卡。一次结果是一张卡，事件是一叠满足要求的卡；事件发生，是实际抽中的那张恰好被圈在里面。',
    [['样本空间 Ω','本次实验所有可能结果组成的清单。','Ω＝{1,2,3,4,5,6}。'],['事件 A','从完整结果清单中选出满足某条件的部分。','A＝{2,4,6}表示偶数。'],['补事件 Aᶜ','完整清单里所有不属于 A 的结果。','本例是{1,3,5}。']],
    'branches',[['完整清单 Ω','1、2、3、4、5、6'],['圈出偶数 A','2、4、6'],['其余 Aᶜ','1、3、5']],
    'A 与 Aᶜ 是完整清单的两部分；实际落到任意一张卡，恰好属于其中一边。',
    [['把一次结果写清楚','本次最终出现 4，这是一次结果；不能说“一次掷骰同时出现 2、4、6”。花括号里的三个点数是事件所包含的三种可能，不是一次一起出现。'],['判断是否发生，只查归属','实际结果 4 位于偶数事件的圈内，所以“偶数”发生；若实际是 5，就不发生。把文字条件译成哪些卡被圈中，比立即背集合符号更直接。'],['反面从完整清单里找','“不是偶数”必须相对于这次骰子的六张卡取剩余部分。若实验改成掷两次，结果卡就要改成点数对，不能继续照搬单次实验的清单。']],
    '本图用有限结果便于画卡片；连续结果也能组成事件，但不能简单靠数卡片求概率。');
  put('prob-frequency','十次里出现三次，是不是概率就等于 0.3？','分清实际统计的比例与模型中的机会。',
    '同一枚硬币掷十次，甲得到三次正面，乙得到六次正面。两份记录都真实，却不能因此说同一模型的机会同时必定等于 0.3 和 0.6。次数比例描述这份数据，概率描述模型中如何分配机会。增加合适的重复次数有助于估计，但不会要求下一次硬币为前面欠下的正面“补账”。',
    [['频数','某事件在这批实验中实际出现的次数。','十次出现三次正面，频数为3。'],['频率','出现次数除以这批实验总次数。','3÷10＝0.3。'],['概率 P(A)','模型给事件 A 分配的机会大小。','公平硬币模型给正面0.5。']],
    'compare',[['甲的记录','3÷10＝0.3'],['乙的记录','6÷10＝0.6'],['共同模型','若公平，P(正面)＝0.5']],
    '两份有限数据可以不同；模型概率不是要求每一批记录的比例都恰好等于它。',
    [['先说清谁是观察值','甲的 0.3 来自已经发生的十次记录，换一批可以变化。它是本批频率，不是把硬币性质直接测成一个绝对准确的小数；也不能因此判定公平模型必错。'],['再说模型作了什么假设','若采用独立且每次正面机会为 0.5 的模型，这个 0.5 是重复实验规则中的参数。数据可用来评估假设，但每份样本自身都有偶然波动，不能跳过不确定性。'],['长期稳定不是短期补偿','合适条件下，频率随次数增加有稳定趋势；已经连出几次反面，不会让独立的下一次正面概率自动变大。总比例接近目标不需要硬币记住过去并主动还债。']],
    '频率稳定需要相应重复条件；规则随时间改变或实验相关时，不能无条件套用独立重复模型。');
  put('prob-axioms','为什么“甲或乙”要减掉重叠部分？','通过数同一批学生理解概率相加与重复计数。',
    '一班十人，六人喜欢篮球，五人喜欢足球，其中三人两样都喜欢。把两张爱好名单直接合并计数，会把那三人每人记两遍。问“至少喜欢一种”的人数时，只能把重复的一份减掉。这就是并集相加减交集的理由：公式不是硬背的补丁，而是在修正同一批对象被数了两次。',
    [['并集 A∪B','满足 A 或 B，包含两者都满足的情况。','至少喜欢一种球。'],['交集 A∩B','同时满足 A 与 B 的情况。','三位两样都喜欢的人。'],['概率可加性','互不重叠的部分，概率可以直接相加。','只篮球、两样、只足球三块相加。']],
    'branches',[['只篮球','6−3＝3人'],['两样都喜欢','3人被名单重复收录'],['只足球','5−3＝2人']],
    '同一班十人的三块互不重叠，合计 3＋3＋2＝8 人；不是两次独立抽取。',
    [['先画人，别急着加百分比','十人是同一份总清单。篮球六人和足球五人有三人重合，所以 6＋5＝11 不是十一位不同学生。先把两样都喜欢的三人放中间，才能看清名单如何重复。'],['把重叠的一份退回去','篮球名单数过中间三人，足球名单又数一次；只需要每人保留一次，减去其中一份三人。于是至少一种为 6＋5−3＝8 人，对应概率为 8÷10。'],['不重叠时才直接相加','若两个事件根本不能同时发生，交集为零，才没有重复要减。至于两件事是否独立，是另一种“机会不受影响”的条件，不等于这里两圈没有交叠。']],
    '人数除以十依赖从班内十人等可能抽一人的模型；一般概率也满足加减关系，但不一定能靠人数比得到。');
  put('prob-classical','为什么不能只数“红红、红白、白白”三种？','识别最底层等可能结果，再合并成关心的事件。',
    '袋里红甲、红乙、白丙三只球，放回抽两次。若只看颜色，会看到红红、红白、白红、白白，但这四种不是同样容易发生：红色本来就有两只球。正确的起点是把每一次抽中的球编号都记录下来，得到九张等可能的结果卡，再把属于目标事件的卡圈出来。',
    [['古典概型','有限个基本结果等可能时，用目标个数除以总个数。','九张编号卡各占1/9。'],['基本结果','在本模型中不再继续合并的单次结果记录。','红甲后白丙是一张卡。'],['等可能','清单中每个基本结果的机会相同。','公平放回抽样使九个编号对等可能。']],
    'memory',[['第一次编号','甲、乙、丙：3种'],['第二次编号','每种后仍有3种'],['目标红红','甲甲、甲乙、乙甲、乙乙']],
    '3×3＝9 个有序编号对等可能，其中红红占 4 个，所以概率为 4/9。',
    [['决定分母之前先确认公平单位','分母不是“我能说出几种颜色词”，而是模型里等可能的基本卡片数。放回抽样下第一次三种、第二次仍三种，按顺序编号共有九种，均占九分之一。'],['把颜色条件落到编号卡上','红红包括甲甲、甲乙、乙甲、乙乙四张卡。四张机会相加得到 4/9。白白只有丙丙一张，为 1/9；这直接说明四个颜色记录不能各分四分之一。'],['始终用同一套清单数','分子必须从分母那九张卡中选择，不能分母用编号对、分子却只数一个“红红”词。写清卡片层级，很多分子分母错位就会立刻暴露。']],
    '本图假设每只球公平、两次放回并按次序记录；不放回或抽取偏向某球时，需要重建基本结果及权重。');
  put('prob-counting','选两个人，和安排第一第二名，差在哪？','用位置有无意义决定排列还是组合。',
    '三位同学甲乙丙，要选两位值日。甲乙与乙甲是同一组选人，所以只能数一次；若安排第一、第二名，甲第一乙第二与乙第一甲第二就不同。所谓排列和组合，先是“哪些结果应视为同一个”的判断。把位置画出来再数，比看见“选”就套一个公式可靠。',
    [['排列','保留不同位置的区别来计数。','第一甲、第二乙与反过来不同。'],['组合','只看选中了哪些对象，不保留内部次序。','甲乙这组与乙甲同一组。'],['阶乘 n!','从 n 乘到1的连乘，用来计位置安排数。','3!＝3×2×1＝6。']],
    'compare',[['有序两格','3×2＝6种安排'],['合并反序','甲乙与乙甲归一组'],['无序选两人','6÷2＝3组']],
    '从三名不同同学中选两名，不重复选人；每个无序二人组恰好对应两种位置安排。',
    [['先给位置命名','若任务有第一和第二两个不同位置，第一格可选三人，第二格只能从剩下两人选，所以共有六种。禁止重复选人是题目的规则，不是乘法自动替你保证的。'],['看交换后是否同一个答案','值日任务只记录组员，把甲乙交换仍是同一组。在六种有序安排里，每组恰好出现两次，于是除以二。若任务保留职位，交换便改变结果，就不能做这一步合并。'],['除掉的是重复次数','三人选两人得到三组：甲乙、甲丙、乙丙。除以二来自每组的内部排列数，而非随意修正。更大问题也要检查每个目标是否都被重复同样多次，才能统一除法。']],
    '本例对象可区分、无放回、每人只选一次；有重复元素、可反复选或位置受限制时，不能直接照搬六除二。');
  put('prob-conditional','已知他戴眼镜，为什么概率要重新算？','把观察范围缩到条件内部，再算其中的比例。',
    '班里十人，四人戴眼镜，其中三人喜欢篮球。随机抽到一位同学后，别人告诉你“他戴眼镜”。此时你的候选清单只剩四人，不再是原来十人；喜欢篮球的候选有三人，所以机会是三除四。条件概率不是在旧概率后随便附一句话，而是改变了现在分配总机会的范围。',
    [['条件概率 P(A|B)','已知 B 发生后，在 B 的范围内重新算 A 的机会。','戴眼镜的人中喜欢篮球的比例。'],['交集 A∩B','既满足目标 A，也满足已知条件 B 的部分。','既戴眼镜又喜欢篮球的3人。'],['分母 P(B)','重新分配机会的条件范围，必须有正概率。','候选只剩4位戴眼镜者。']],
    'branches',[['原班十人','原来的候选范围'],['已知戴眼镜','保留4人'],['其中篮球爱好者','3÷4＝0.75']],
    '从同一班等可能抽一人，条件信息把十人清单缩为四人；目标计数也必须同时满足这个条件。',
    [['把“已知”落实为筛选','告诉你戴眼镜，不会改变这位同学的爱好，却改变你用于判断的候选范围。先把不戴眼镜的六人划掉，再讨论剩下人的机会，这就是竖线后条件的作用。'],['目标也必须留在新范围内','要数的是“既戴眼镜又喜欢篮球”的三人，不是全班所有喜欢篮球的人。把三除以四得到条件比例；把三除以十回答的则是两个条件一起满足的原始概率。'],['读符号时明确谁是条件','P(A|B) 读作在 B 发生条件下 A 的概率，不能随意调成 P(B|A)。前者从眼镜者里找篮球爱好者，后者从篮球爱好者里找眼镜者，分母往往不同。']],
    '本例条件有正概率且班内等可能抽取；连续变量“恰等于某值”的条件不能直接用有限人数公式除以零。');
  put('prob-total-bayes','知道产品坏了，怎样倒查它来自哪条线？','先按来源计算缺陷总量，再在坏品中分来源比例。',
    '甲线做八成产品、坏品率百分之一；乙线做两成、坏品率百分之四。看到坏品，不能只因乙线坏得更频繁就说一定来自乙线。还要看两条线原本各做多少。假想一万件，甲做八千坏八十，乙做两千也坏八十，坏品里两边恰好各半。先把数量画出来，“倒过来问来源”就不神秘了。',
    [['全概率','把互不重叠且覆盖全部的来源分别算贡献，再加起来。','坏品总数80＋80＝160。'],['贝叶斯公式','获得结果信息后，重新计算各来源占比的规则。','坏品中甲线占80/160。'],['先验 / 后验','看见新信息前的来源机会 / 看见信息后的来源机会。','甲线原占80%，已知坏品后占50%。']],
    'branches',[['甲线 8000件','坏1% → 80件'],['乙线 2000件','坏4% → 80件'],['坏品池 160件','甲乙各占一半']],
    '按一万件假想总体展示比例；坏品池汇总的是两条线对同一结果的贡献，不是直接比较1%与4%。',
    [['先乘来源份额','甲线的坏品贡献需要把“来自甲”和“甲线上坏”接在一起：8000×1%＝80。乙线同样算2000×4%＝80，单看坏品率高低会漏掉来源规模。'],['把结果池合起来','两条线覆盖全部产品，来源不重叠，所以坏品总数是160。对应总坏品率160/10000＝1.6%。这是先由来源推结果的全概率计算，没有倒查的步骤。'],['在结果池里重新分份额','现在已知拿到坏品，候选范围缩到160件。来自甲的80件占一半，这就是后验来源机会。分母必须是所有坏品，而不是甲线全部8000件，两种分母回答不同问题。']],
    '比例模型假设两条线覆盖全部来源且给定坏品率适用；现实数据偏差或漏掉其他来源会改变后验，不能把条件反转当等式。');
  put('prob-independence','不能同时发生，和互不影响，是一回事吗？','用骰子事件分开互斥与独立。',
    '掷一枚骰子，“出现1”和“出现2”不能同时成立；知道出了1，出2的机会立刻变成零，所以它们其实很互相影响。另一组条件：“点数为偶数”和“点数不大于4”，知道后者后，偶数仍占一半，这才是不改变机会。画出共同结果，就能看见“互斥”和“独立”是在回答两个不同问题。',
    [['互斥','两个事件没有共同结果，不能同时发生。','单次点数1与点数2。'],['独立','一个事件发生不会改变另一个的概率，满足相应乘法关系。','偶数与不大于4在公平骰模型下独立。'],['乘法判据','检验 P(A∩B) 是否等于 P(A)P(B)。','共同有2、4两面，2/6＝(3/6)(4/6)。']],
    'compare',[['互斥例子','点数1 与 点数2'],['独立例子','偶数 与 不大于4'],['共同结果检查','2、4：共2面']],
    '同一枚公平六面骰：互斥看有没有交集，独立看交集的概率是否等于边际概率的乘积。',
    [['先问能否一起成立','点数1和点数2没有共同卡片，因此互斥。两者原概率都为1/6，但知道点数1后，点数2已不可能，条件概率变成0，说明互斥并没有保证不影响。'],['再问范围内比例是否改变','偶数为2、4、6，占三面；不大于4为1、2、3、4。只看后面四面时，偶数有2、4，占二分之一，与原来一样，所以这组条件符合独立。'],['用数字交叉检查','共同成立的两面概率2/6，两个单独概率乘积是(3/6)×(4/6)，也为1/3。这里只是公平骰中这一组事件的性质，换一个阈值就需要重新检验。']],
    '独立取决于完整概率模型；两个正概率互斥事件不独立，零概率等边界情形需按定义判断。');
  put('prob-mutual-independence','每两件都互不影响，三件一起就安全吗？','看懂两两独立为何不足以推出相互独立。',
    '独立掷两枚公平硬币，记 A 为第一枚正面，B 为第二枚正面，C 为两枚同面。知道第一枚正面，同面仍有一半机会；知道第二枚也是这样，所以每两件都看似互不影响。但若同时知道前两枚都正面，同面就必然成立。第三个条件已经被前两个合起来决定，不能只做两两检查。',
    [['两两独立','每次只取两个事件，它们都满足独立关系。','A与C、B与C都可独立。'],['相互独立','任意一组事件一起发生的概率，都符合各自概率乘积。','不仅要查两件，也要查三件。'],['联合事件','几个条件同时满足形成的新条件。','A与B同时发生只剩正正。']],
    'memory',[['四张等可能卡','正正、正反、反正、反反'],['两两共同','每一对共同占1/4'],['三者共同','正正：1/4，不是1/8']],
    'A、B、C 各概率1/2；任意一对独立，但三者同时概率1/4不等于(1/2)³。',
    [['先把四张结果卡固定','两次独立公平抛硬币给出四个等可能有序结果。A圈正正、正反，B圈正正、反正，C圈正正、反反，各圈中两张卡，所以单独概率都为一半。'],['两两检查确实都能通过','A与B、A与C、B与C共同都只留下正正一张，概率四分之一，等于一半乘一半。不能因为最后结论失败，就否认这些两两独立计算本身是对的。'],['三者一起要增加一项检查','A、B、C同时成立仍只有正正，概率四分之一；若相互独立应为八分之一。知道A与B后C已确定，正好说明组合信息可以揭示单独看不到的联系。']],
    '这是事件独立性的反例，不表示所有两两独立构造都失败；要求相互独立时，必须按定义检查所有需要的联合关系。');
  put('prob-random-variable','为什么给随机结果再贴一个数字标签？','把实际结果与从结果算出的数分开。',
    '掷两枚硬币，记录为正正、正反、反正、反反。若只关心正面有几枚，就给四张结果卡分别贴上2、1、1、0。数字标签把两张不同卡归成1，却没有让实验重新发生。随机变量就是从结果到数字的规则；字母X代表这套规则和所得数字，不是随便变化的未知数。',
    [['随机变量 X','给实验结果按固定规则配上数字的函数。','X表示两枚中的正面数。'],['取值','这套规则可能输出的数字。','本例X可为0、1、2。'],['事件 {X＝1}','所有被规则贴成数字1的原始结果。','正反和反正两张卡。']],
    'branches',[['正正','标签2'],['正反、反正','共同标签1'],['反反','标签0']],
    '两枚公平独立硬币的四张卡等可能；标签1来自两张卡，因此标签本身并非三等份。',
    [['先保留原始卡片','一次实验真正落到的是某个硬币组合，例如正反。只要记录方式不变，正反和反正仍是不同结果；给它们相同数字，只是后续观察把两种情况归到同类。'],['规则必须事先说清','设X数正面枚数，就规定正正映到2、正反与反正映到1、反反映到0。若改成“第一枚是否正面”，那是另一随机变量，同一次结果也会得到不同标签。'],['概率跟着原卡片汇总','要求P(X＝1)，就把标签为1的两张卡概率相加，得到1/2，而不是三个取值各分1/3。随机变量的数字大小并不自动决定它的概率，需要回到实验模型。']],
    '本例是有限结果到数字的映射；连续随机变量同样有固定取值规则，但一般不能靠简单数卡片来分配机会。');
  put('prob-discrete-law','数字和机会，怎样排成一张不漏账的表？','能读懂并检查离散随机变量的分布律。',
    '一天卖出的花束可能是0、1、2束，机会分别是0.2、0.5、0.3。把数值与机会配对，就得到分布表。它不是把三天的真实销量排在一起，而是事前描述“一天会落在哪种数值”。概率不能负，完整取值的概率相加必须为一；否则机会账没有记平。',
    [['分布律','列出离散变量每个可能值及其对应概率。','0配0.2，1配0.5，2配0.3。'],['离散','取值可以一个个列举，有限或可数。','一天销量用非负整数记录。'],['归一化','所有可能值的机会加起来等于1。','0.2＋0.5＋0.3＝1。']],
    'memory',[['X＝0','概率0.2'],['X＝1','概率0.5'],['X＝2','概率0.3']],
    '完整模型只允许0、1、2束，三格互不重叠且总概率为1；没有把“最常见”当作必然。',
    [['先检查数值与机会是否配对','每一格要读成完整一句话：一天卖1束的机会是0.5。不能把0.5当销量，也不能把取值1当这类结果必出现一次；表中一行是在说明一种可能。'],['把整张账合起来','三种情况覆盖本模型所有可能，概率总和为0.2＋0.5＋0.3＝1。若还可能卖3束，就不能一面保留这三个概率总和为1，一面额外再加一个正概率取值。'],['合并条件就把相应格相加','至少卖1束包括取值1与2，两格互斥，机会为0.5＋0.3＝0.8。这是按事件选格，不是把两个销量数值相加成3后再去查表。']],
    '数值和概率是教学假设，不代表真实花店数据；无限可数取值也需检查总和，不能漏掉尾部概率。');
  put('prob-binomial-poisson','是数固定十次的成功，还是数一小时来了几人？','用计数对象区分二项模型与泊松模型。',
    '做十道题，记答对几道，问题先规定了十次尝试；数一小时进店几人，问题先规定的是时间窗口，并没有预先固定来客尝试总次数。两者都输出整数，背后机制却不同。二项模型给每次相同成功机会并要求独立；泊松模型用一个窗口的平均到达数描述计数，是否适用仍需检查到达机制。',
    [['二项分布 B(n,p)','n次独立、每次成功机会p相同，统计成功次数的模型。','10次尝试，每次成功0.2。'],['泊松分布 Pois(λ)','用正参数λ描述一段窗口内计数的模型，均值为λ。','一小时平均来3人，λ＝3。'],['参数','固定模型中决定机会分配的数字，不是每次观测值。','λ＝3不要求每小时恰好3人。']],
    'compare',[['固定尝试次数','10次中成功几次？'],['固定观察窗口','1小时到达几次？'],['先核对机制','独立、同概率或到达规则']],
    '两类计数模型比较；固定窗口并不自动推出泊松，固定次数也不自动满足独立同成功率。',
    [['二项先确定机会格子数','十次试验各只有成功或失败，且独立、成功概率同为0.2，才可用二项模型。成功次数介于0与10；若某题成败改变下一题难度，就要重新考虑这些假设。'],['泊松把注意力放在窗口','若某到达机制可用泊松计数，参数λ＝3表示这一小时平均到达数为3，而不是固定三次上限。出现0、1、2或更多次都可能，概率由同一λ决定。'],['相同平均数不能替代机制','两种模型都可能平均为2，但计数上限和机会分配不一定相同。在很多独立小概率机会的条件下可考虑泊松近似；不是看见稀少事件就无条件换公式。']],
    '课堂到达情境只是建模提示；成团到达、强依赖、成功率改变时需检验假设，近似误差也应评估。');
  put('prob-cdf','沿数轴往右走，已经收进来多少机会？','把分布函数读成不大于阈值的累计概率。',
    '把销量0、1、2的机会0.2、0.5、0.3放在数轴上，拿一把尺子从左往右扫。扫到0时收进0.2，扫到1时再收0.5，合计0.7，扫到2就收满1。分布函数就是“阈值左边连同阈值本身，总共装了多少机会”的记录。它的高度是累计量，不能和某一格的单独概率混为一谈。',
    [['分布函数 F(x)','事件X不大于阈值x的概率，即P(X≤x)。','F(1)＝0.7。'],['跳跃大小','离散取值处累计函数增加的量。','到1时增加0.5。'],['单调不减','阈值往右移，已收进的概率不会被减掉。','0.2→0.7→1。']],
    'timeline',[['扫过0','累计0.2'],['扫过1','累计0.2＋0.5＝0.7'],['扫过2','累计1']],
    'X只取0、1、2，概率依次0.2、0.5、0.3；箭头表示阈值增大，不是销量按时间依次发生。',
    [['先读清小于等于','F(1)包括X＝0和X＝1，所以是0.7，不只是取值1的概率0.5。等号尤其重要，在离散取值点直接决定那一格的机会是否已经被收入。'],['格子之间累计量不变','阈值从1移到1.5，没有新增可取值，因此F仍为0.7。分布函数画成台阶，是因为机会集中在几个点；不是说变量真的沿台阶缓慢移动。'],['区间机会用累计差','求1<X≤2，可用F(2)−F(1)＝1−0.7＝0.3。若左边也包含1，就不能不加检查照减；先把端点是否包括写明，再把累计量相减。']],
    '本图是离散台阶例子；一般分布函数都单调不减且右连续，但不一定处处可导或对应密度。');
  put('prob-density','曲线高过1，为什么概率仍然没超标？','把密度当浓度，把概率当区间面积。',
    '候车时间被简化为0到半小时之间均匀分布。每一小时长度对应的密度为2，看上去大于1，却没有错误：可用区间只有0.5小时，长方形面积2×0.5才等于1。密度的高度不是“恰好这个时刻”的概率；真正分配给一段时间的机会，要把这一段上方的面积取出来。',
    [['概率密度 f(x)','单位长度附近分配机会的浓度，不是该单点的概率。','半小时区间上密度为2/小时。'],['积分 / 面积','把区间中各小段的密度贡献累加。','宽0.1小时、高2，面积0.2。'],['单点概率','连续密度模型给恰好某一个精确点的概率为0。','恰好0.2小时不占一段宽度。']],
    'memory',[['完整宽度','0至0.5小时'],['恒定高度','密度2/小时'],['一小段面积','0.1×2＝0.2']],
    '均匀等待模型：整个长方形面积1，一小段宽0.1小时的面积0.2；高度2本身不是概率。',
    [['先检查横轴单位','若横轴用小时，区间长度是0.5，密度单位是每小时。改用分钟，长度变30、密度变1/30，面积仍是1。高度随单位改变，更说明它不是一个不变的单点概率。'],['用宽乘高看一段机会','在均匀例子中，任意0.1小时长且完整位于范围内的区间，概率都为0.1×2＝0.2。曲线不恒定时需把小块加总成积分，核心仍是面积而不是单独高度。'],['精确一点不占面积','一条竖线宽度为0，所以连续模型里某个精确等待值概率为0。这不表示实验不能得到某个数，而是无限精细标签下，每个单点都没有正的概率份额。']],
    '结论针对具有密度的连续模型；若存在离散点质量，应分别计算，不能把所有分布都强行看作普通曲线面积。');
  put('prob-uniform-exponential','等机会落在区间，和越等越久，是同一种等待吗？','从具体等待规则区分均匀分布和指数分布。',
    '班车严格每十分钟一班，你在一班之间等机会到站，剩余等待可用0到10分钟均匀模型。另一情形是某泊松到达机制下等下一位客户，常用指数等待模型：已经等五分钟而仍没到，后续等待的分布不因这五分钟变老。两种都叫等待，却有不同机制，不能仅凭题目出现“时间”就选同一个公式。',
    [['均匀分布','在给定区间内，相同长度分到相同机会。','十分钟内每一段两分钟机会相同。'],['指数分布','正等待时间的一类分布，用正速率λ描述，尾概率为e^(−λt)。','λ＝每分钟0.2时平均等待5分钟。'],['无记忆性','已等过s仍未发生后，再等t的机会规律与起初相同。','已等5分钟不使后续等待自动缩短。']],
    'compare',[['定时班车','均匀到站位置→剩余0至10'],['随机到达等待','指数模型→无固定上限'],['已等一段','是否改变后续规则？']],
    '并列比较两种假设；均匀模型有上限，指数模型无记忆，不能把一套性质移给另一套。',
    [['固定发车要看你怎么到站','十分钟一班并不足以直接说等待均匀，还需你在一班间隔内等机会到站。此时等待超过十分钟不可能，已经等八分钟后最多再两分钟，显然会受已等时间影响。'],['指数由另一套到达机制支持','在适合的泊松到达假设下，下一次间隔可用指数分布。λ是单位时间平均到达速率，不是某一分钟必到的次数；平均等待1/λ也不等于每次都等相同时间。'],['用条件问题看无记忆','指数模型问“已经等了s且仍没来，再等超过t的机会”，答案与一开始等超过t相同。这里条件是事件尚未发生；不是说系统对所有历史都无关，更不是所有等待都如此。']],
    '均匀需要到站时刻假设；指数无记忆针对相应等待模型。预约、周期性、老化或速率变化都可能使这些模型失效。');
  put('prob-normal','身高差10厘米，和误差差10毫米，怎样用同一把尺？','把正态变量先减中心、再除尺度，得到可比较的位置。',
    '一组测量平均100、波动尺度5，看到110，比中心高两个尺度。另一组平均1000、尺度50，看到1100同样高两个尺度。标准化先去掉中心，再用各自尺度作单位。钟形曲线说明机会怎样围着中心分布，不是任何中间多两边少的数据都自动正态。',
    [['正态分布 N(μ,σ²)','由中心μ和正尺度σ决定的一类对称钟形分布。','本例μ＝100、σ＝5。'],['标准化 Z','用(X−μ)/σ把位置换成离中心几个尺度。','110对应Z＝2。'],['标准正态','中心0、尺度1的正态分布，可用统一表或软件查概率。','同一Z位置用同一累计表。']],
    'flow',[['原测量110','中心100，尺度5'],['先减中心','110−100＝10'],['再换单位','10÷5＝2个尺度']],
    '这里σ为标准差，σ²才是方差；模型若正态，标准化后才可使用标准正态概率。',
    [['中心不同先平移','110本身不说明高低，必须与所属模型的中心100比较。减去100得到偏离10；对另一组中心1000的测量，这个比较基准会不同，不能直接拿原始数字判断稀有程度。'],['再问偏离占多少常见波动','用标准差5作单位，10÷5＝2，表示比中心高两个标准差。分母要用σ而非σ²；方差25的单位已平方，拿它直接当长度尺度会把位置算错。'],['概率查的是阈值方向','要求超过110，就转为P(Z>2)；若查表给P(Z≤2)，还要用1减去它。标准化保留同一事件的机会，没有把“超过”自动变成“以下”或双侧范围。']],
    '减中心除尺度本身不让任意数据变正态；使用正态表需要相应模型或合理近似，且σ必须为正。');
  put('prob-transform-monotone','摄氏度改成华氏度，机会去了哪里？','理解单调换标签保留事件概率，并检查不等号方向。',
    '一支温度计记录摄氏温度X，另一支把同一温度换写成Y＝2X＋10。数值标签变大，真实情况没有换一批；“Y不超过30”正是“X不超过10”。求新变量分布，先把新条件翻回旧标签最稳妥。若换标签规则向下走，比如Y＝−X，大小顺序会倒过来，不等号也必须翻向。',
    [['变换 Y＝g(X)','把原变量每个取值按固定函数改成新数值。','Y＝2X＋10。'],['单调','旧值增大时，新值始终同向增大或始终减小。','2X＋10递增，−X递减。'],['反解事件','把Y的阈值条件改写成关于X的同一事件。','Y≤30等价于X≤10。']],
    'flow',[['新条件','Y≤30'],['代入规则','2X＋10≤30'],['回到旧变量','X≤10，概率不变']],
    '图为严格递增线性换标签，三句话描述同一批结果；不是三次独立实验。',
    [['别先改概率，先改条件','Y并没有把原结果重新抽一次。要算P(Y≤30)，先写成P(2X＋10≤30)，问的是原来哪些结果能落进这个范围；概率仍由原X模型分配。'],['按代数一步步反解','两边减10得到2X≤20，再除以正数2得到X≤10。若原X有分布函数F，答案就是F(10)，无需先凭直觉猜新曲线的高度应该乘几倍。'],['遇到递减规则翻转方向','若Y＝−X，则Y≤−3意味着−X≤−3，两边除以−1后为X≥3。端点是否含等号还要结合离散或连续情况；反解事件比照搬公式更少漏边界。']],
    '此图用一一对应的递增规则；非单调变换可能让多个旧值落到同一新值，需要合并所有来源，不能只取一个反解。');
  put('prob-transform-many','平方后正负都变同一个数，漏掉一边会怎样？','先找出新事件的所有原始来源，再汇总概率。',
    '把一个可能为正也可能为负的测量误差X平方，得到Y＝X²。误差＋2和−2都会变成4，结果像把数轴两边向中间折过来。要求Y不超过4，必须同时保留−2到2整段，而不是只保留X≤2。非单调变化的难处就在于一个新数值可能有多个旧来源，图一折，漏掉的一半就看得见。',
    [['多对一变换','不同旧取值可以变成同一新取值。','＋2和−2平方后都是4。'],['原像','所有会被规则送进目标条件的旧取值。','X²≤4的原像是−2≤X≤2。'],['累计概率','先找到完整旧范围，再按旧模型算机会。','连续时可算F(2)−F(−2)。']],
    'branches',[['左边来源−2','平方后到4'],['右边来源＋2','平方后也到4'],['目标Y≤4','旧范围是[−2,2]']],
    '平方把左右两侧合并；求区间概率应回到完整原范围，端点点质量须按原模型处理。',
    [['先检查新值可能在哪里','平方结果不能小于0，所以任何负阈值y都给P(Y≤y)＝0。先写出新变量的可能范围，可以防止把对所有实数成立的分布公式错误延伸到不可能区域。'],['把条件拆成左右界','对y＝4，X²≤4等价于|X|≤2，也就是X同时不小于−2且不大于2。这是两条边界共同限制的一段，而不是“X≤2”这一半无限长范围。'],['合并来源时保留原来的权重','若求新密度，正负反解都可能贡献，且拉伸比例也要考虑；只搬来正根会漏掉左边质量。初学先用分布函数反解区间，确认来源完整后再研究密度公式。']],
    '连续情形端点概率为零时可直接用累计差；离散点质量需要检查含不含端点，不能机械照搬同一减法。');
  window.PLAIN_BEGINNER = Object.assign(window.PLAIN_BEGINNER || {}, data);
})();
(() => {
  const data = {};
  const put = (id, plainTitle, goal, story, terms, kind, nodes, caption, steps, boundary) => { data[id] = {plainTitle,goal,story,terms:terms.map(([word,meaning,example])=>({word,meaning,example})),diagram:{kind,nodes:nodes.map(([name,detail])=>({name,detail})),caption},steps:steps.map(([title,text])=>({title,text})),boundary}; };
  put('prob-process-slices','每次结果不再是一个数，而是一整条曲线，会怎样？','从固定时刻和固定一次实验两种视角认识随机过程。',
    '测同一类设备一整天温度，一次实验留下随时间变化的一条曲线；换一台或重做一次，得到另一条。固定下午三点看很多次实验，温度是一个随机变量；固定某次实验顺着一天看，就是一条轨迹。随机过程把这两个方向放进同一张图，别把“许多时刻”误认为“许多次独立实验”。',
    [['随机过程 {X(t)}','按时间等指标排列的一族随机变量。','每个时刻有一个温度变量。'],['样本轨迹','固定一次随机结果后，随时间展开的整条记录。','某一天从早到晚的温度曲线。'],['时间切片','固定某一时刻，比较不同实验可能的值。','很多设备下午三点的温度。']],
    'compare',[['固定一次实验','沿时间得到一条轨迹'],['固定下午三点','跨实验得到一个随机变量'],['合起来看','时间×实验结果两方向']],
    '温度过程的两种观察方向；沿一条轨迹的不同时间点一般不自动独立同分布。',
    [['一次实验可以产生整条线','传统例子一次抽签只给一个数字，这里一次设备运行给出一整天曲线。每条线是一种可能的完整结果，不能把线上的每个点都重新叫一次独立重复。'],['固定时刻仍回到随机变量','把时间锁在三点，不同实验会给不同温度，所以X(三点)有自己的分布。这是一条横穿许多轨迹的切片，跟拿同一天许多时刻当同分布样本不同。'],['两种方向回答不同问题','轨迹关心一台设备怎样随时间起伏；切片关心同一时刻的总体机会。后续均值函数、相关函数和平稳性，都是在明确这两种方向后才有意义。']],
    '时间指标可连续也可离散；轨迹记录与重复实验分布不能互换，是否能用单条长轨迹推总体需另加条件。');
  put('prob-process-moments','平均也随时间变时，怎样描述一群曲线？','用均值函数和两时刻协方差分别记录中心与共同波动。',
    '早上温度与晚上温度可能有不同平均，所以过程的平均通常不是一个常数，而是每个时刻各有一个。再看早上高于自己平均的设备，晚上是否也常偏高，就需要两个时刻的协方差。均值函数像很多曲线的平均轮廓，协方差函数像时刻之间的连线账，两者不能只用一条观测曲线直接当真值。',
    [['均值函数 m(t)','每个时刻随机变量的期望。','早上均温20、晚上均温25。'],['协方差函数 C(s,t)','两个时刻各减自身均值后的共同偏动平均。','比较早晚偏差乘积。'],['二阶矩','平方或两项乘积的平均，需相应有限性。','方差为C(t,t)。']],
    'compare',[['早上时刻s','先减早上平均'],['晚上时刻t','先减晚上平均'],['连接两时刻','偏差相乘再平均']],
    '中心可随时间变化；C(t,t)描述单时刻方差，C(s,t)还保留两个时刻的联系。',
    [['每个时刻减自己的中心','早上20、晚上25，不能统一减20后说两项偏差。m(t)依时间给出相应平均，固定时刻时仍是对实验总体求期望，不是沿一天先取时间平均。'],['正负乘积说明一起怎样偏','同一设备早晚都高于各自均值，乘积为正；一高一低为负。跨实验按机会平均这些乘积得到C(s,t)，其符号不是简单由两时刻原温度高低决定。'],['单点宽度只是特殊情况','让s＝t，两个偏差相同，乘积变平方，所以C(t,t)就是该时刻方差。完整C还告诉不同时间如何关联，只有各时刻方差不足以描述轨迹记忆。']],
    '均值和协方差需相应矩存在；这些二阶特征一般不唯一决定整个过程分布，单轨估计也需另论。');
  put('prob-process-joint','每天都一半高一半低，曲线连接方式就确定了吗？','认识同样单时刻分布可对应完全不同的时间依赖。',
    '每天测量值都可能为＋1或−1，各占一半。第一种设备第一天抽一次正负，之后一直保持；第二种每天重新独立抽正负。每个固定日期的机会表完全一样，画出的轨迹却截然不同：一种整条不变，一种会跳动。只给每个时刻的分布，没有交代时刻之间怎么连接，所以还不够描述随机过程。',
    [['单时刻分布','只看一个固定日期的数值机会。','每天各有一半±1。'],['有限维联合分布','同时看若干指定日期数值组合的机会。','P(X₁＝1,X₂＝1)。'],['依赖结构','不同日期的值如何共同出现。','保持同号与每天重抽不同。']],
    'compare',[['共同单时刻表','每天±1各半'],['模型甲','第一天定号，之后不变'],['模型乙','每天独立重抽正负']],
    '两个过程边缘相同；甲两天同为＋1概率1/2，乙对应概率1/4，联合分布不同。',
    [['先确认单天确实相同','无论甲还是乙，任取一天都各半为正负，所以单天均值、方差也一样。不能因为这些摘要完全一致，就宣布两种设备运行规律一致。'],['把两个日期一起问','甲第一天为＋1时第二天必为＋1，所以两天都正概率1/2；乙独立重抽，联合为1/4。一个两时刻问题已经揭示单天表格隐藏的差别。'],['描述过程要保留联合信息','原则上各有限组日期的联合分布共同描述过程的概率规律。学习时不必一开始写无限多表，但要知道每个新增时刻都涉及与旧时刻怎样连接，而非只补一份边缘表。']],
    '单时刻同分布不意味着时刻独立或轨迹相同；只有特别模型条件下，少量均值协方差可确定完整联合规律。');
  put('prob-process-poisson','数到现在共来几人，和下一小时又来几人，独立吗？','分清累计计数与不重叠区间增量。',
    '两小时共来了四人，第三小时又来一人，于是三小时累计五人。累计数彼此包含，不能说前两小时总数和前三小时总数独立；泊松过程的独立性说的是不重叠时间段各新增多少。恒定速率λ把时长换成平均新增量，N(t)沿时间只会不减，是计数而非每刻重新抽一个无关数字。',
    [['N(t)','从起点到时刻t的累计事件次数。','N(2)＝4，N(3)＝5。'],['增量 N(t+h)−N(t)','在接下来h长窗口里新增的次数。','第三小时新增1。'],['泊松过程速率λ','恒定单位时间平均到达率，增量为Pois(λh)。','每小时3人则两小时均值6。']],
    'timeline',[['到2小时','累计4人'],['第3小时窗口','新增1人'],['到3小时','累计4＋1＝5人']],
    '齐次泊松过程的计数关系；独立增量针对不重叠时间窗口，不是针对相互包含的累计N值。',
    [['累计值共享旧事件','N(3)已经包含N(2)数过的四人，因此知道前值会限制后值，后值至少不小于它。不能把每个时刻的泊松边缘分布直接理解成逐时独立抽签。'],['独立的是分离窗口新增量','在齐次泊松模型下，不重叠区间增量独立，同长度窗口分布相同。用λ乘窗口长度得到该增量均值，注意小时和分钟单位要一致。'],['速率恒定仍是建模假设','饭点客流成团、一天速率变动都可能破坏简单齐次模型。观察到均值接近λ并不足以确认独立增量，需要结合到达机制和数据检查。']],
    '图采用齐次泊松过程；成团、速率变化或依赖到达需其他模型，累计值不具有所述不重叠增量独立性。');
  put('prob-process-wiener','每段新增扰动独立，当前位置也独立吗？','认识维纳过程的连续轨迹、正态增量与位置共享历史。',
    '把微小随机扰动不断累积，当前位置保留了此前所有扰动。标准维纳过程从0开始，长度为h的一段新增量均值0、方差h，不重叠段的新增量独立。于是后一个位置包括前一个位置，并不独立。轨迹连续也不意味着平滑到可以当普通速度曲线求导，这个模型同时拥有连续和粗糙两种特征。',
    [['标准维纳过程 W(t)','从0出发，具独立平稳正态增量与连续轨迹的过程。','W(0)＝0。'],['正态增量','长度h的新增量服从N(0,h)。','时间加长，增量方差随h增大。'],['位置与增量','位置累积旧扰动，增量只描述某一段新增。','W(2)＝W(1)＋新增。']],
    'flow',[['起点W(0)＝0','先无累积'],['走过第一段','得到W(1)'],['再加第二段','W(2)包含W(1)']],
    '图示累积关系而非三段直线轨迹；W(1)与后段增量独立，但与W(2)一般相关。',
    [['先看独立关系的对象','独立的是不重叠时间段的新增扰动，而不是整条线上每个位置。W(2)使用了第一段扰动，和W(1)共享历史，所以两者协方差不为零。'],['时间决定增量的尺度','一段长h的增量方差为h，标准差才是√h。把时间翻四倍，典型尺度翻两倍，不是四倍；这份扩散尺度区别于以固定速度直线运动。'],['连续并非可当光滑曲线','模型轨迹没有跳跃，却典型地非常粗糙，不能把它当作处处存在普通导数的确定曲线。把随机游走画成折线可帮助直觉，但那只是近似，不是维纳样本路径本身。']],
    '本图为标准维纳模型；连续不保证可微，独立的是增量，模型近似现实扰动还需时间尺度与机制支持。');
  put('prob-markov-state','只看现在就够，前提是“现在”记全了什么？','把马尔可夫性理解成当前状态对过去预测信息的概括。',
    '棋盘上下一步走哪里，可能只由当前所在格和固定转移规则决定；这时过去绕过哪些格，不再增加对下一步的预测。但若规则还要看连续停留几次，只记当前位置就不够，状态还得加上停留计数。马尔可夫不是说世界没有记忆，而是你定义的“现在”已经装下需要的过去信息。',
    [['状态','模型用来概括当前预测所需信息的记录。','可能是位置，也可能位置加计数。'],['马尔可夫性','给定当前状态后，未来相应条件分布不再依赖更早状态。','下一步按当前格的规则抽。'],['转移概率 Pᵢⱼ','从当前状态i到下一步j的概率。','每一出发行的概率和为1。']],
    'flow',[['过去经过很多格','完整历史'],['当前状态装够信息','位置或扩充记录'],['下一步分布','按当前状态决定']],
    '条件信息的概括图；是否有马尔可夫性取决于状态定义与模型，不能从“只写一个状态”自行推出。',
    [['先说明状态记录哪些量','若只记录棋盘位置，要确认规则确实只看位置。若还依赖走到这里用了多久，单纯位置遗漏信息，先前历史仍能改善预测，原模型就不满足所需性质。'],['比较有无更早历史的预测','马尔可夫关系说在当前状态已知后，再告诉更早状态不改变下一步条件分布。不是说当前与过去独立，也不是说未来数值完全由现在确定。'],['必要时扩充状态','把所需停留次数一起加入状态，可能恢复足够的信息概括。状态变大有成本，但比在不满足性质时强套转移矩阵更诚实，预测目标也需跟着重新明确。']],
    '状态充分性是模型条件；马尔可夫不等于逐步独立，也不自动表示转移概率不随时间改变。');
  put('prob-markov-power','两步到B，为什么要把中间每条路都算上？','按中间状态分路，理解矩阵乘法。',
    '有A、B两个状态：A到A机会0.8、到B为0.2，B到A为0.3、留B为0.7。从A两步到B，可能先到A再到B，也可能先到B再留B。每条路线按条件机会相乘，再把两条互斥路线相加，得到0.30。矩阵乘法把“遍历中间站”的操作整齐压进了行列计算里。',
    [['转移矩阵P','每行给一个出发状态，列给下一步目标的概率表。','A行是0.8、0.2。'],['P²','两步转移概率矩阵，来自P与P相乘。','不是每格直接平方。'],['中间状态求和','对所有可能中间站分别乘路线再相加。','0.8×0.2＋0.2×0.7。']],
    'branches',[['经A中转','A→A→B：0.16'],['经B中转','A→B→B：0.14'],['两路合并','两步到B共0.30']],
    '同一齐次二状态链，转移行约定为出发、列为到达；两条中间路线互斥且覆盖全部。',
    [['固定起点与终点','先问从A到B共两步，不是任意起点平均。第一步中间状态只有A或B，这两路不能在同一次两步路径中同时成立，所以最终需要相加。'],['同一路线按条件相乘','经A为0.8×0.2＝0.16，经B为0.2×0.7＝0.14。这里利用当前状态决定下一步规则及齐次转移，不是声称两次所处状态彼此独立。'],['矩阵内积正是在遍历','P²的A行B列就是上述两个乘积之和。若有更多状态，要再加其他中间站；逐格平方只会漏路，不能算作两步转移矩阵。']],
    'P的幂用于齐次链；时变转移需按时间顺序乘不同矩阵，行列约定也必须始终一致。');
  put('prob-markov-balance','人一直在两边走，比例怎样还能不变？','用流入流出平衡解释平稳分布。',
    'A地有六成人、B地四成人。每步A中两成去B，B中三成去A，双方流动都占总人数0.12，于是来去抵消，整体六四比例保持不变。平稳分布说的是这种分布层面稳定，不是个体不动，也不是说任意初始比例都会立刻等于六四。先画流量，再看πP＝π就有了现实含义。',
    [['平稳分布π','经过一步转移后仍保持不变的状态概率份额。','πP＝π，概率和为1。'],['概率流','某状态份额乘相应转移机会。','0.6×0.2＝0.12。'],['总体平衡','某状态新份额等于来自所有状态的流入总和。','流出流入抵消可保持份额。']],
    'compare',[['A份额0.6','去B：0.6×0.2＝0.12'],['B份额0.4','去A：0.4×0.3＝0.12'],['下一步份额','仍是A0.6、B0.4']],
    '二状态链P的两向转移为0.2与0.3；本例双向流平衡，不等于所有链都需要逐对详细平衡。',
    [['份额与转移概率要相乘','A里20%去B，指A那一群的20%，占全体是0.6×0.2。不要直接把A份额减0.2，因为转移概率不是自动按全体人数作分母。'],['计算一步后的总份额','A留下0.6×0.8＝0.48，再加B流来0.4×0.3＝0.12，共0.6。B同样保持0.4，这就是把当前份额向量乘P后仍不变。'],['存在不等于必会收敛','求出π只是找到了固定分布；从任意初始状态能否趋向它，需要链的结构条件。每个人仍能移动，稳定的是跨大量重复或群体的状态机会分配。']],
    '平稳分布不保证个体停止或任意初始分布收敛；逐对流相等是更强条件，不能由一般πP＝π强求。');
  put('prob-markov-classes','路能不能回来，比算很多步更先要看什么？','用可达、周期与吸收结构判断长期问题。',
    'A可以去B，B可以去C，C进去后不再离开。即使算出很多步概率，也要先看到这张路网不是人人互通，C还是终点。另一些路网要求每次A到B、B到A，只能偶数步回A，会产生周期。不可约、吸收、周期这些词，首先是图上能走哪些路、多久能回来的描述。',
    [['可达 / 不可约','可达是有正机会路径；不可约是任意两状态能互相到达。','A→B→C不表示C能回A。'],['吸收状态','进入后以概率1留在该状态。','C的自转移P_CC＝1。'],['周期','正概率返回步数集合的最大公约数。','严格A↔B时周期2。']],
    'flow',[['A','能去B'],['B','能去C'],['C吸收','进入后只留C']],
    '可达路网示意而非完整转移数字表；箭头代表存在正概率路径，不表示各条同概率。',
    [['互通要求双向都能走','A能经B去C，却没有从C回A的路，这张图不可约条件失败。不能只看图画在一个区域里就说“连通”，有向概率路径的方向非常重要。'],['吸收是进入后的规则','C里下一步仍在C的概率为1，表示一旦进入便不会离开。能否一定最终进入还要看起点、其他分支与概率，不能只凭图中画了一个终点就省去分析。'],['返回步数决定周期','另一个严格交替A与B的链，只能2、4、6等步返回A，最大公约数为2。周期不是肉眼看见某个环长度就定，必须考虑所有有正概率返回的步数。']],
    '结构词以正概率路径定义；周期需看所有返回步数，吸收存在也不自动说明从每个起点都必然吸收。');
  put('prob-markov-limits','明明有平稳分布，为什么每天仍来回跳？','用周期反例分清存在、唯一与收敛。',
    '每天必定A转B、B转A。如果开始就在A，第一天B、第二天A，分布永远交替，不会安静靠近某一份比例。但若初始就各一半，交换后仍各一半，所以平稳分布确实存在。这说明“存在一个不变分布”和“从每个起点都会收敛到它”是不同句子；周期性正是阻碍后者的一种结构。',
    [['平稳分布','转移后保持不变的概率向量。','本例(1/2,1/2)。'],['收敛分布','从指定初始分布出发，n步后分布的极限。','从A出发交替，没有此极限。'],['非周期条件','排除被固定节奏卡住的返回结构。','有限不可约非周期链有常用收敛结论。']],
    'timeline',[['起点全在A','分布(1,0)'],['一步全在B','分布(0,1)'],['两步回A','继续永远交替']],
    '确定性交替的二状态链：平稳分布存在且唯一，却不从全在A的初始分布收敛。',
    [['先验证固定分布确实存在','若两边各一半，下一步全部交换，整体仍各一半，因此πP＝π成立。不要因为某个初始轨迹不收敛，就反过来说该链没有平稳分布。'],['再看指定起点是否趋近','从A确定出发时，偶数步A概率1、奇数步0。这一序列没有单一极限，虽然它的时间平均份额可有另一种行为，但那不等于每步分布收敛。'],['使用定理先检查结构','有限不可约非周期链有常见的唯一平稳及收敛结论。本例不可约却周期2，缺少非周期条件；无限状态链还要考虑正再生等要求，不能照搬有限版本。']],
    '分布收敛、时间平均与平稳存在是不同问题；有限链结论不可省略结构条件后推广到所有无限状态链。');
  put('prob-stationary-types','一条曲线一直动，统计规律也能“不动”吗？','区分严格平稳与只保持一二阶规律的宽平稳。',
    '海面每秒都起伏，平稳不是要求高度保持一条直线，而是把观察起点平移后，相关统计规则不变。严格平稳比较整组时刻的联合分布；宽平稳只要求均值恒定、方差有限，以及两时刻协方差只看间隔。两种要求强弱不同，不能看某条轨迹大致围着零就直接当作已经证明平稳。',
    [['严格平稳','任意有限组时刻一起平移后，联合分布不变。','比较整段概率规律。'],['宽平稳','均值恒定，二阶有限，协方差只依时间差。','C(s,t)可写为C(t−s)。'],['滞后τ','两次观察之间相隔的时间。','相隔一小时而非具体几点。']],
    'compare',[['轨迹仍可起伏','不是数值恒定'],['严格比较','全部有限维联合规律'],['宽平稳比较','均值与滞后二阶结构']],
    '图比较平稳定义的对象，不是凭一幅有限曲线直接判定总体性质。',
    [['把不变的对象说清','平稳讨论分布或某些统计量不随整体移时改变，轨迹仍可有随机波动。连续某段上涨也未必否定平稳，单条记录只是模型的一次实现。'],['宽平稳先查三件事','均值是否同一常数，方差是否有限且一致，协方差是否只依间隔而不依绝对日期。只看到均值差不多，还没检查完后两项，就不能直接宣布宽平稳。'],['两种定义有条件联系','严格平稳若二阶矩存在可推出宽平稳；没有有限二阶矩时不能这样说。反过来宽平稳一般不够，联合高斯等特殊结构下才可得到更强联系。']],
    '严格平稳转宽平稳需二阶矩存在；有限图形与样本均值稳定只是线索，不能代替总体定义与假设。');
  put('prob-stationary-phase','每条线都像正弦波，随机从哪里开始有什么作用？','用均匀随机相位解释振荡轨迹与平稳统计可以并存。',
    '所有钟摆都以同样节奏、幅度2振荡，但开始时随机落在一圈的不同位置，且每个角度等机会。某一个钟摆一直上下动；很多钟摆同一时刻却总有人高、有人低，平均抵消为零。时间前移只相当于给所有起始角加同一角度，均匀分布仍不变，所以这种随机相位模型可平稳。',
    [['随机相位Θ','在周期中开始的位置，按角度记录。','Θ在0至2π均匀。'],['过程 X(t)','本例为2cos(ωt＋Θ)，ω为固定角频率。','幅度2，起点随机。'],['平移不变','加同一角度后，绕一圈均匀分布仍均匀。','这是平稳性的来源。']],
    'flow',[['整圈等机会起步','Θ均匀于0至2π'],['各自随节奏振荡','幅度2，频率固定'],['时间平移','只把均匀相位整体转圈']],
    '固定幅度、固定频率、均匀随机相位模型；振荡不妨碍统计移时不变。',
    [['先看随机在哪里','随机的是起始相位Θ，不是每个时刻重新抽一个独立正弦值。选定Θ后，一条完整轨迹已经按相同节奏展开，不同时刻因此有很强关系。'],['均匀相位让中心不偏','同一时刻，整圈相位等机会，对应正负高度对称，平均为0。本例平方平均为幅度平方的一半，即2；这份方差恒定不说明轨迹自身不动。'],['一起移时不改联合规律','时间统一增加h，所有角度都加ωh，均匀整圈分布不变，所以不只是单时刻分布相同，整组时刻关系也一起保留。固定相位则一般没有同样结论。']],
    '结论依赖相位均匀等设定；若起始角固定或分布偏向某处，均值可能随时间变化，不能只凭正弦外形叫平稳。');
  put('prob-stationary-ergodic','盯一台设备够久，能代替同时看很多台吗？','用随机常量过程说明平稳不自动保证时间平均等于总体平均。',
    '一批设备出厂时各随机选＋1或−1，之后永远保持这个读数。任意日期看全体，平均都是0，模型平稳；但你只盯住一台，即使观察一百万天，时间平均仍是它的＋1或−1，不会变成0。各态历经研究的就是：一条长记录何时能代替很多次实验来估某种总体特征，不能只由平稳两个字保证。',
    [['总体平均','固定时刻跨随机实验求平均。','一半＋1一半−1，均值0。'],['时间平均','沿同一条轨迹把多个时刻的值平均。','某设备始终＋1，时间平均1。'],['均值各态历经','长时间平均按相应意义趋近总体均值的性质。','比宽平稳多一层要求。']],
    'compare',[['设备甲轨迹','始终＋1'],['设备乙轨迹','始终−1'],['总体均值','两种等机会，平均0']],
    '随机常量X(t)＝Z，Z等机会±1；过程平稳，但单轨时间平均不能估出总体均值0。',
    [['先验证它确实平稳','整体时间平移后，所有记录仍是同一个随机常量Z，联合规律没有变化，所以这个反例不是偷偷用了非平稳过程。平稳与能否单轨估总体需要分别看。'],['再对一条轨迹算平均','若这次抽到Z＝1，所有时刻都是1，平均多久也为1；抽到−1同样。增加时间点没有获得新的变化来源，不能把一百万个相同依赖值当一百万份独立信息。'],['各态历经要针对特征','有的条件保证均值时间平均收敛，估协方差还需相应要求。不能泛说“能观察很久就全都知道”，应说明估哪个总体量、按何种收敛意义、凭哪些依赖条件。']],
    '平稳不自动各态历经；不同均值、相关等特征有不同要求，长时间记录也不等于同样多的独立样本。');
  put('prob-stationary-covariance','随便画一条好看的相关曲线，都能是真模型吗？','用方差非负性检查协方差函数的共同约束。',
    '若每个时刻方差是1，却声称相隔一秒的协方差是2，这已经不可能：两个同尺度量的共同线性变化不能强过它们自身波动的限制。相关函数还必须让任何几个时刻的加权组合都得到非负方差。它不是任意连几个点就能成立的漂亮曲线；对称、界限和整组合法性要一起检查。',
    [['协方差函数 C(τ)','平稳过程相隔τ的两项共同偏动。','C(0)是方差。'],['对称与界限','实值过程C(−τ)＝C(τ)，且|C(τ)|≤C(0)。','C(0)＝1时不能C(1)＝2。'],['半正定','任意有限时刻加权组合的方差都非负。','是整组数的共同约束。']],
    'flow',[['零滞后给方差','C(0)＝1'],['候选滞后值','若C(1)＝2已超界'],['完整函数检查','还要满足半正定']],
    '图以中心化实值宽平稳过程说明；只过对称和单点界限检查还不足以证明全函数合法。',
    [['零点不是随意的高度','两时刻重合时偏差乘自己，就是平方，所以C(0)必须等于非负方差。若变量并未去均值，常用相关R(0)是二阶矩，不要把R与中心化C混作同一量。'],['先做容易的必要检查','交换两时刻不改乘积，实值协方差呈偶对称；共同偏动还有|C(τ)|≤C(0)约束。给出C(1)＝2、C(0)＝1可立刻判不合法，省去复杂变换。'],['整组方向也不能出负方差','选几个时刻，用任意实系数组合成新变量，它的方差必须≥0。这一要求同时约束很多滞后值，叫半正定；单独每个值都没超界不代表组合一定合法。']],
    '实值二阶平稳模型才有这里的形式；必要检查不是充分证明，复值或未中心化相关需按各自定义调整。');
  put('prob-stationary-spectrum','起伏主要慢慢涌，还是快速抖，怎样换个角度看？','把时间间隔相关转成频段上的二阶波动分配。',
    '同样总波动，一种海面缓慢起伏，另一种细碎快速抖动。协方差按时间间隔问“隔多久还相似”，功率谱按频率问“哪些节奏贡献更多波动”。谱峰高不等于总方差大，还要看宽度与面积。先去平均，再说采用哪种频率单位和变换约定，才能让频域的预算正确回到原来的波动单位。',
    [['角频率ω','每单位时间相位转多少弧度，区别于每秒多少周期。','ω＝2πf。'],['协方差谱','中心化过程二阶波动的频域描述。','本课S是C的傅里叶变换。'],['谱线 / 谱密度','集中在某频率的质量 / 连续分布的频率浓度。','随机相位正弦有谱线。']],
    'compare',[['时间侧提问','隔多久还相似？'],['频率侧提问','慢节奏还是快节奏？'],['总波动核对','按约定积分回C(0)']],
    '连续时间角频率约定：C(0)＝(1/2π)∫S(ω)dω；普通密度式需相应可积条件。',
    [['频率图换的是描述语言','慢相关衰减常对应更集中的低频贡献，快变化可分散到较宽频段。谱描述二阶结构，不是在承诺轨迹由几个确定正弦精确组成，也不一定决定非高斯完整分布。'],['先核对面积约定','本课程连续角频率S定义把1/(2π)放在逆变换，因此总方差是谱面积再除2π。换成每秒周期或另一种谱定义，系数会移位，不能脱离约定直接比较数字。'],['集中谱线不强行画成普通高度','随机相位正弦有固定频率谱线，不能只用光滑谱密度覆盖；未去均值还会在零频增加固定平均的贡献。看到强低频，先区分平均偏置与随机波动。']],
    '谱通常只描述二阶信息；谱线需谱测度处理，普通积分式有可积等条件，频率单位与2π归一必须一致。');
  put('prob-stationary-discrete-spectrum','每天采一次，为何频谱只看一圈就够？','认识离散频率周期、采样尺度与白噪声平谱。',
    '只在整数时刻看旋转，频率ω和ω＋2π每次都多转完整一圈，采样点完全一样，所以离散频谱以2π为周期。通常看−π到π一段就够。白噪声在非零滞后没有线性相关，谱在这段平坦；平坦说的是各频率二阶贡献相同，不表示时间点必独立，更不表示每天一采和每秒一采有相同物理周期。',
    [['离散角频率','单位为弧度每采样间隔，按2π重复。','ω与ω＋2π在整数点不可区分。'],['白噪声谱','二阶白噪声协方差只在零滞后非零，对应平谱。','本课f＝σ²/(2π)。'],['混叠','不同连续频率在采样点上留下相同序列。','采样太疏会误认真实节奏。']],
    'flow',[['只在整数点采样','多转2π看不出来'],['一圈频率范围','通常−π到π'],['白噪声平谱','积分面积为σ²']],
    '本课离散谱f含1/(2π)，在−π至π的直接积分为方差；与连续时间S约定不同。',
    [['先把采样间隔写在旁边','同样离散频率0.2弧度每步，若一步一天或一秒，现实周期截然不同。没有时间单位的频谱峰，不能直接翻成某种小时或季度规律。'],['周期来自整数相位相同','对整数n，额外2πn是整圈，所以e的相应复指数不变。这解释只需一个频率周期，而不是把连续时间谱的整条实轴积分生搬过来。'],['平坦也要说明尺度','零均值白噪声只有γ(0)＝σ²，其他滞后协方差0，因此本约定给f＝σ²/(2π)。宽2π的平面面积为σ²；白噪声不相关仍不等于一般独立。']],
    '离散谱有周期且受采样间隔约束；单边双边与频率单位会改变面积约定，平谱也不自动证明时刻独立。');
  put('prob-timeseries-white','有日期顺序的数据，为什么不能当一袋散装样本？','保留时间依赖，并区分二阶白噪声、独立和高斯条件。',
    '十天用电量先升后降，排序后虽然还保留常见数值，却丢掉了连续高峰和反弹。时间序列研究的正是这些顺序关系。白噪声是常用基准：平均零、方差恒定、不同时刻协方差零；它排除线性相关，却不自动排除所有依赖。实际只看到一条有限记录，自相关小也不是对总体独立性的证明。',
    [['时间序列','按时间顺序观察的一列数据及其过程模型。','日期是信息的一部分。'],['二阶白噪声','零均值、恒方差、不同时间不相关的序列。','可有非线性依赖。'],['样本自相关','用有限序列估计滞后相关的结果。','真为0时样本值也会波动。']],
    'compare',[['保留日期','看连续高峰与反弹'],['排序成一袋数','丢掉时间连接信息'],['白噪声基准','无非零滞后线性相关']],
    '图比较数据组织与二阶定义；不相关、独立、联合高斯是不同条件，不能自动互换。',
    [['一条序列不等于独立重复','相邻日可能共享天气或需求，n天未必提供n份独立信息。把记录随机打散可能破坏要研究的依赖，也会使面向未来的训练验证混入未来。'],['白只排除线性记忆','按这里定义，不同滞后协方差为0，但平方或更复杂函数可能有联系。若另有独立或联合高斯条件，才能使用更强结论，不能只凭“白噪声”三个字省略。'],['有限图像保留抽样误差','样本自相关不可能每格都精确0，看很多滞后时也会偶然出现突出点。结合模型、业务和残差检查，把未发现明显相关与证明完全随机区分开。']],
    '白噪声定义以本课二阶约定为准；样本图是证据线索，非独立证明，时间不等间隔也需另处理。');
  put('prob-timeseries-ar','今天偏高4，明天会留下多少昨天的影子？','用冲击衰减理解因果平稳AR(1)与单位根边界。',
    '把每天值减去长期平均，记成偏差Y。模型Y今天＝0.5倍昨天偏差＋今天新扰动，表示旧影响留下半份。若今天有一次额外冲击4，之后暂时没有新冲击，它会留下4、2、1这样的痕迹。真实轨迹还会不断加新扰动，所以这条衰减线只是单次冲击贡献，不是每天实际值必按固定比例下降。',
    [['AR(1)','用上期自身值和本期扰动描述的自回归模型。','Yₜ＝φYₜ₋₁＋εₜ。'],['系数φ','上一期偏差留下的比例与方向。','0.5减半，−0.5反向减半。'],['因果平稳','由当前过去扰动稳定构成的常见版本。','通常要求|φ|<1。']],
    'timeline',[['一次冲击','贡献4'],['下一步','φ＝0.5时留下2'],['再下一步','留下1，并继续衰减']],
    '仅画单次冲击在无后续新增冲击时的贡献；实际路径还叠加每期扰动。',
    [['先把水平减成偏差','Y是X减长期均值，不是随便把方程截距当均值。若写Xₜ＝c＋φXₜ₋₁＋εₜ，平稳均值通常为c/(1−φ)，c与均值职责不同。'],['旧扰动按幂次留下','一次冲击4经过h步贡献4φ^h。本例每步减半；φ为负则交替方向，绝对值接近1则衰减很慢，过去很久仍可能影响今天。'],['平稳与预测条件分开查','常用因果版本要求|φ|<1，φ＝1成为随机游走，不能继续套稳定方差公式。若要把线性预测叫条件期望，还需创新对过去条件均值零等相应要求。']],
    '图讲常用因果AR(1)，不是所有数学解的完整分类；白噪声与独立创新不同，单位根不能套平稳公式。');
  put('prob-timeseries-maarma','今天和昨天，共享的是旧观察还是旧扰动？','区分MA的扰动组合、AR的过去观测与可逆性条件。',
    '设每天新扰动为ε，今天读数等于今天扰动加半份昨天扰动。明天也会带半份今天扰动，所以相邻读数共享一份来源，会有关联；隔得更远没共享项，二阶关联可消失。这是移动平均模型MA，不是简单把最近几个已观察值求平均。ARMA再把过去自身与过去扰动两种记忆放进同一方程。',
    [['MA(1)','当前扰动加一份上期扰动的模型。','Yₜ＝εₜ＋θεₜ₋₁。'],['ARMA(p,q)','同时含过去观测与过去扰动的模型族。','p、q为两种结构的阶数。'],['可逆性','能由当前与过去观测稳定恢复扰动的性质。','与因果平稳是不同问题。']],
    'branches',[['今天Yₜ','使用εₜ与εₜ₋₁'],['明天Yₜ₊₁','使用εₜ₊₁与εₜ'],['共同来源','两者共享εₜ']],
    '加号约定的MA(1)共享噪声图；白噪声不相关使非共享项协方差消失，未额外声称全部独立。',
    [['先圈出相同扰动编号','把相邻两项展开，只有εₜ编号重复，因此它贡献邻接协方差；相距超过一阶没有共同编号，二阶协方差可为0。这比先背截尾口诀更容易看见原因。'],['移动平均不是观测平滑','模型加的是不可直接看到的扰动，权重也不必相同或加到1。把最近三天观测简单求均值是一种数据平滑，不能只因为中文同名就当作MA模型。'],['两种根条件别混','有限MA由平稳白噪声线性组合可宽平稳，可逆性却是能否稳定恢复扰动的额外条件。ARMA还要按所用正负号检查多项式根，不能把根在圆外误说成系数在圆外。']],
    '本课采用MA加号约定；平稳、因果与可逆要分别检查，共享项解释二阶关系，不自动证明完整独立。');
  put('prob-timeseries-difference','账户余额一直累积，先看每天增减会怎样？','明确差分对象、还原水平以及过度差分风险。',
    '账户余额100、103、102，变化为＋3、−1。差分把“现在共有多少”改成“这期多了多少”，有时变化比水平稳定。若预测以后增加2再增加1，就从最后102接回104、105，不能把2、1当余额。差分不是万能按钮，多做一次还可能制造负相关。',
    [['一阶差分ΔXₜ','本期水平减上期水平。','103−100＝3。'],['ARIMA(p,d,q)','先做d次普通差分，再用ARMA描述的模型标记。','d记录差分次数。'],['还原预测','把预测变化量按时间接回已知水平。','102＋2＝104，再＋1＝105。']],
    'flow',[['原水平','100、103、102'],['相邻相减','变化3、−1'],['预测后接回','末值102→104→105']],
    '差分与还原的数值示意；第三节点假设后续预测变化为2、1，并非由前三点自动推断。',
    [['差分改变了变量的含义','ΔXₜ代表本期新增量，少了一个起始观察，仍保留时间顺序。水平单位与变化单位虽相同，任务却不同，不能把差分列与原日期位置错对。'],['先判断需要怎样处理趋势','随机游走一阶差分可变成创新，确定趋势则可能用另一种建模处理。两条短图都上升，不足以证明同一种非平稳原因；差分次数应由模型与诊断支持。'],['还原点值不等于相加区间','从102加未来预测变化可得水平点预测；各步误差却可能相关，不能把每步区间端点直接加起来冒充正确水平区间。过度差分也会放大噪声或引入负相关。']],
    '差分针对特定结构，不保证得到平稳；还原误差需处理相关性，普通差分与季节差分也不是同一个操作。');
  put('prob-timeseries-workflow','站在第80天，模型能看见第90天的数据吗？','让训练、预处理、选模与验证共同遵守时间边界。',
    '有一百天销售记录，要检验未来预测能力，就只用前八十天，再看后面表现。若随机打乱，模型可能用第九十天帮助预测第八十一天；标准化或填缺失用全段也会泄露未来。问题是“站在预测那一天，当时知道什么”，所有步骤都要服从这条线。',
    [['训练 / 测试','用来建立模型的过去数据 / 模拟未见未来的留出数据。','前80天与随后20天。'],['信息泄露','处理或选择过程使用了预测当时不可知信息。','全段均值参与前段标准化。'],['滚动验证','逐日只用已发生数据预测下一步，再揭晓真值。','重现每天真实预测场景。']],
    'timeline',[['第1至80天','只用这段训练预处理'],['预测第81天','此刻不看未来真值'],['揭晓后再前进','扩窗或滚窗预测下一天']],
    '时序验证的信息流程；模型选择、缺失处理与基线比较也必须遵守同一时间边界。',
    [['先把所有可知信息列清','预测第81天时可用第80天真实值，但不能用第82天真实值填第81天缺失。模型之外的标准化、趋势估计与特征制作也属于分析，不能把偷看藏在预处理里。'],['滚动制造真实未知','先用历史预测一天，揭晓后再加入训练，继续下一天。用同样时点、步长和指标比较复杂模型与最后值等基线，避免因测试日期不同而误把优势归给模型。'],['诊断通过仍需说明边界','残差暂未发现明显相关，不证明真模型或未来永久有效。制度变化、异常冲击和模型选择都会影响预测，报告应区分训练拟合、未来验证与实际预测区间。']],
    '验证需模拟真实可知信息；测试段反复用于选模型会失去独立评估作用，结构变化也可能使历史表现不再适用。');
  window.PLAIN_BEGINNER = Object.assign(window.PLAIN_BEGINNER || {}, data);
})();
(() => {
  const data = {};
  const put = (id, plainTitle, goal, story, terms, kind, nodes, caption, steps, boundary) => { data[id] = {plainTitle,goal,story,terms:terms.map(([word,meaning,example])=>({word,meaning,example})),diagram:{kind,nodes:nodes.map(([name,detail])=>({name,detail})),caption},steps:steps.map(([title,text])=>({title,text})),boundary}; };
  put('prob-anova-idea','三组平均不同，是方法不同，还是组内太吵？','用组内波动作为尺子衡量组间均值差。',
    '三种方法样本均值为60、70、80。若每组成绩紧贴本组均值，组间差醒目；若每组散得很开，同样差异证据就弱。方差分析用组内噪声校准组间信号，名称谈方差，常见检验目标却是总体均值是否相同。整体拒绝只说至少一组不同，不是每两组都不同。',
    [['组间波动','各组平均相对总体样本平均的偏离。','60、70、80之间的差别。'],['组内波动','每个观察相对本组平均的散开。','同一方法下学生仍有不同成绩。'],['F统计量','把组间与组内的适当均方相除。','信号相对于噪声有多大。']],
    'compare',[['组均值不变','仍是60、70、80'],['组内很紧','差异相对噪声醒目'],['组内很散','同样差异证据变弱']],
    '单因素经典方差分析的信号与噪声比较；实际F标定还依赖独立、正态、等方差等模型条件。',
    [['先把问题说成均值假设','零假设是三种方法的总体均值都相同，不是三组当前样本均值必须恰好一样。抽样本来会使样本均值不同，所以需要一把能衡量波动的参照尺。'],['相同差异要结合组内噪声','若学生围着各自组均值很紧，组间差就相对大；若组内散得很开，样本均值差可能更容易由随机波动形成。F将两类平方波动按自由度校准后比较。'],['整体结果不指定哪一对','拒绝共同均值只表明至少有差别，不能直接宣称所有组两两不同。要定位差别需预定对比或适当多重比较，并同时看差异大小与研究设计。']],
    '经典F结论依模型条件；不等方差、依赖或选择偏差需另处理，多次普通两两检验也会增加总体误报。');
  put('prob-anova-table','平方和、自由度、均方，分别在算哪本账？','把ANOVA表的每一列接回具体加减乘除。',
    '三组各两人，成绩分别1和3、4和6、7和9，组均值2、5、8，总均值5。组均值之间的平方差要乘每组人数，得到组间平方和36；组内每人离本组平均正好1，六个平方相加为6。两类总账除以各自可变方向数，才成为可比较的均方；最后18除2得到F＝9。',
    [['平方和SS','把相应偏差平方后加总的总账。','组间36、组内6。'],['自由度df','该项平方波动包含的独立变化方向数。','三组组间2，组内6−3＝3。'],['均方MS','平方和除以对应自由度。','36/2＝18，6/3＝2。']],
    'flow',[['平方和总账','组间36，组内6'],['除各自自由度','分别除2与3'],['均方相除','F＝18/2＝9']],
    '三组各两人示意，数值便于手算；计算F不等于小样本已足以验证正态与等方差假设。',
    [['组间账要考虑每组人数','组均值离总均值分别−3、0、3，每组有两人，所以组间平方和是2×(9＋0＋9)＝36。不能只加三个均值偏差而忘记它们各代表两个人。'],['组内账围着各自组均值','每组两人都离本组平均1，总共有六个1²，因此组内平方和6。组内自由度为每组人数减一后相加，三组各1，总计3。'],['表格最后才生成比值','组间自由度2，均方18；组内自由度3，均方2，相除为9。F的参照有两个自由度，分别2和3，不能只报一个9就跳过模型与p值解释。']],
    '表中分解对应有截距的单因素模型；数值例子仅帮助读表，检验有效性仍需抽样与误差条件。');
  put('prob-two-way-additive','行和列都影响结果，一格只有一次测量够吗？','理解双因素加法分解与不能单独估计交互作用的限制。',
    '两种机器在三天各生产一次，每个机器与日期组合只有一个结果。可设机器和日期各带一份影响，加到共同水平上。若机器优势随日期反转，就是组合额外影响；但每格仅一次，常规模型难把交互与随机误差分开。无重复分析需明确没有交互等前提。',
    [['因素','用于分组或解释结果的一项类别条件。','机器与日期是两个因素。'],['加法模型','共同水平加行效应、列效应，再加误差。','假设机器效果不随日期改变。'],['交互作用','一个因素的效果随另一因素水平而改变。','某机器只在某天特别占优势。']],
    'compare',[['机器行效应','不同机器的平均差'],['日期列效应','不同天的共同起伏'],['每格一条数据','交互与误差难分开']],
    '无重复交叉设计的模型限制图；没有重复不等于交互不存在，只是信息不足以按通常方式分离。',
    [['先把两种分组同时保留','不能先按机器比较、又独立按日期比较，却忽略两者交叉。每一条数据都应明确属于哪台机器、哪一天，这样才能写出行与列共同解释的模型。'],['加法意味着效果不翻转','若机器甲比乙多2单位，加法模型要求各天都保留相同机器差异。日期可以整体抬高或压低所有机器，但不改变这个差；这是一个实质假设，不是自然定律。'],['一格一次留下识别限制','每格只有一个值，额外组合偏差与随机噪声会混在剩余项中。要单独研究交互通常需要重复或额外结构；不能把模型没写交互当成数据证明没有交互。']],
    '无重复设计需明确加法等前提；没有可单独估计的交互项，不代表现实交互为零，F检验也依误差条件。');
  put('prob-two-way-interaction','两种方法平均相同，为什么分人群后完全反转？','用效果差的变化认识交互，并理解重复的价值。',
    '方法甲在第一类人均值80、第二类60，方法乙恰好60、80。两类等权合并后两方法都平均70，看起来没差；但适合谁完全不同。交互作用就是方法差随人群改变，不能用一个统一差概括。每种组合有多个观察，才能另外估计组内随机波动，再判断这种效果翻转是否超出噪声。',
    [['主效应','对另一因素按相应方式平均后的整体差。','两方法等权平均都70。'],['交互作用','一项因素差异依另一因素水平而变。','甲对乙的差从＋20变−20。'],['重复','同一因素组合下有多条合适独立观察。','帮助估计组合内随机噪声。']],
    'compare',[['第一类人','甲80，乙60：差＋20'],['第二类人','甲60，乙80：差−20'],['合并平均','甲乙都70，掩盖翻转']],
    '两类等权的教学均值；交互表现为差的差40，不代表任意真实数据都等权或具有因果解释。',
    [['先比较每类内部差异','第一类甲减乙为20，第二类甲减乙为−20，差异方向发生翻转。交互不是简单看四个均值是否不全相同，而是看因素效果是否随另一因素变化。'],['合并可能把效应抵消','等权合并使甲乙均值同为70，主效应可接近零却仍有强交互。因此看到总体差不显著不能立刻说任何人群都没差，研究问题要保留组合层次。'],['重复把信号与噪声分开','同一组合有多条观察，才可用组合内散开估计误差。图中只给均值，还不能判断显著性；还需要样本量、误差尺度以及独立、正态与方差等模型检查。']],
    '例子用等权均值说明交互；不平衡设计解释更需谨慎，四个均值本身不足以作显著或因果结论。');
  put('prob-regression-fit','一条线不可能穿过所有点，怎样选得最合适？','把竖直残差平方总和作为最小二乘的选择目标。',
    '记录学习时长与成绩，同样两小时的人也会得不同分。一条直线用来概括给定时长的平均关系，不负责穿过所有点。对每个点，先用直线给出预测，再用实际成绩减预测形成竖直残差。最小二乘选择截距和斜率，让这些残差平方的总账最小；不是让所有方向的几何距离都最小。',
    [['回归直线','用截距加斜率乘x描述平均关系的线。','ŷ＝a＋bx。'],['残差e','观察y减拟合值ŷ的差。','实际6、预测5，残差1。'],['最小二乘','选择参数使残差平方和最小。','把正负差平方，避免抵消。']],
    'flow',[['给定x','先由候选直线预测ŷ'],['实际减预测','e＝y−ŷ'],['平方后汇总','比较不同直线的总账']],
    '图示普通最小二乘竖直误差目标；它不自动包含横坐标测量误差，也不保证真实关系是直线。',
    [['先认清预测对应的方向','给定学习时长x，用候选线产生分数ŷ，然后看实际y比它高低多少。距离沿y方向量，而非点到线的垂直几何最短距离，两种拟合问题目标不同。'],['平方总账避免正负抵消','某点残差−1，另一点＋1，直接相加为0却显然没有全部拟合正确。平方后各贡献1，得到总误差2，才让不同线能按同一非负目标比较。'],['最优线仍不是事实定律','求出的a、b只是在所选样本与目标下最优，样本外可能弯曲或制度变化。斜率单位是分数每小时，改x单位会改数字，不能把系数大小脱离单位比较。']],
    '最小二乘是一种拟合准则；作区间与检验还需误差条件，且相关直线不自动证明学习时长的因果效应。');
  put('prob-regression-inference','预测“两小时的人平均几分”和“下个人几分”一样吗？','分开均值置信区间与单个新观察的预测区间。',
    '固定学习两小时，直线估出平均70分。估计这类人的平均成绩，需要考虑直线参数估计误差；预测下一位同学的具体成绩，还要加上他自己的个体差异。所以预测区间通常更宽。两个区间都可能围着70展开，却回答不同问题；不能拿均值区间当作未来大多数个体的活动范围。',
    [['均值置信区间','推断给定x处总体平均反应的区间。','两小时人群的平均分。'],['预测区间','预测给定x下一个新观察值的范围程序。','下一位同学的分数。'],['残差噪声','个体值相对平均关系的随机散开。','新个体额外带来波动。']],
    'branches',[['同一x＝2小时','拟合均值70'],['问人群平均','只有平均关系估计误差'],['问下一个人','再加个体随机波动']],
    '在同一经典回归模型和置信水平下比较；个体预测通常比平均反应区间更宽。',
    [['先写预测对象是谁','“两小时人群平均”是一个固定但未知的条件均值；“下一位学生”是带个体波动的新随机值。若问题没写清，软件两种interval选项都能跑，却可能回答错问题。'],['两个不确定性来源不同','平均关系估计会随训练样本变化，形成均值区间；未来个人还会偏离真实平均，所以预测误差再多一份残差噪声，不能因拟合线漂亮就把这份省掉。'],['样本范围外更要谨慎','在观察过的学习范围内尚能用模型条件评估区间，外推到二十小时未必仍符合线性关系。软件返回很精确的端点，也不能让没被验证的外推自动可靠。']],
    '经典区间依赖相应线性与误差假设；预测对象、条件x与范围需明确，模型错误不一定包含在计算区间中。');
  put('prob-multiple-regression','“其他条件相同”到底是在图里固定了什么？','把多元回归系数读成模型内条件比较，而非自动因果。',
    '成绩与学习时长和原有基础都可能有关。多元回归把两项一起放进模型，时长系数描述保持基础等其他项不变时，平均成绩怎样改变。这不等于现实已随机让某人多学一小时，也不保证遗漏因素都被排除。先说“模型里固定什么”，才不会随意作因果承诺。',
    [['多元回归','用多个解释变量共同描述响应平均关系。','y≈a＋b₁时长＋b₂基础分。'],['偏回归系数','模型中固定其他项时，一项每增一单位对应的均值变化。','b₁单位为分/小时。'],['共线性','解释变量在样本中强相关，难分各自作用。','时长与练习次数几乎总一起变。']],
    'branches',[['输入学习时长','模型内比较多1小时'],['固定基础等项','不是删掉它们'],['解释平均分变化','按b₁描述条件比较']],
    '线性加法模型的条件解释图；固定其他项是模型比较，不代表完成真实随机干预。',
    [['每个系数附着自己的条件','b₁不是时长与成绩简单两项相关，而是在模型写入的其他变量固定时的比较。若加入或删去变量，系数可改变，因为比较条件已改变，不必自动视为软件出错。'],['变量一起变会难拆份额','时长和练习次数若总同步，模型很难知道成绩变化该分给哪一项，系数可能不稳定。高拟合度并不保证每个系数都估得精确，还要看标准误和设计信息。'],['调整不等于控制了所有混杂','没有测量的动机、健康等因素仍可能影响解释；某些变量也不应随意调整。观察回归的条件系数与因果效应之间，还需要研究设计和因果假设搭桥。']],
    '模型内条件比较不自动因果；遗漏、错误调整、共线性及范围外组合都会限制系数解释和预测。');
  put('prob-bootstrap-world','只有一份数据，怎样模拟“再抽一批”？','把经验分布当暂时替身，用有放回重抽估计统计量波动。',
    '手里只有2、4、9三条独立样本，想知道均值换一批会怎样。自助法先把这三个值当作临时小总体，每个占三分之一，再有放回抽三次，可能得到2、2、9，也可能4、9、9。每份重抽样都重新算均值，许多均值的散开用来近似抽样波动；这没有凭空增加真实独立资料。',
    [['经验分布','把已有观测按样本份额组成的替身总体。','2、4、9各占1/3。'],['bootstrap样本','从替身总体有放回抽出与原样本同规模的数据。','允许2在一份中重复。'],['重抽统计量','每份重抽样上重新计算目标。','每份都算一次平均。']],
    'flow',[['原样本','2、4、9'],['放回抽三次','例如2、2、9'],['重新计算均值','重复得到一团均值']],
    '普通独立同分布非参数bootstrap示意；三点小样本仅用于认识操作，不保证近似足够好。',
    [['先承认替身不是完整总体','原总体未知，自助法用样本所显示的分布暂代它。三个数给出的支持很有限，重抽不会制造样本之外的新取值，也不能自动补回原采样没覆盖的人群。'],['有放回与同规模都重要','每次从2、4、9中抽一项后放回，再抽下一项，所以一份中可重复。每份仍三条，才能模仿原统计量在相同样本量下的波动，不能换成任意规模而不解释。'],['重算目标而非只看数据散开','若研究均值，每份都算均值，汇成均值分布；若研究中位数，就每份算中位数。原数据标准差与这些统计量的重抽标准差职责不同，不能混用。']],
    '普通版本依赖抽样结构和统计量条件；重抽次数增加只减模拟误差，不会增加原样本信息或修复选择偏差。');
  put('prob-bootstrap-interval','一团重抽均值，怎样读出标准误、偏差和区间？','把三种输出对应到三个不同问题。',
    '重抽后得到很多个均值。它们散得多开，估计的是均值的标准误；它们的中心离原均值多远，可用于估计偏差；挑两端分位数，则形成百分位区间思路。这三个数字来自同一团模拟，却不是同一种含义。尤其把重抽均值中间95%圈出来，不等于已经证明区间在真实总体下精确95%覆盖。',
    [['bootstrap标准误','重抽统计量的标准差，用来近似目标统计量抽样波动。','不是原数据的标准差。'],['bootstrap偏差','重抽统计量平均减原样本统计量。','比较两处中心。'],['百分位区间','用重抽统计量两端分位数作区间端点。','常取2.5%与97.5%位置。']],
    'compare',[['看散开宽度','估计标准误'],['看中心偏移','估计偏差'],['看两端分位','构造百分位区间']],
    '同一团重抽统计量的三种读法；区间覆盖质量仍依bootstrap近似与统计量条件。',
    [['先区分数据与统计量分布','样本值2、4、9本身的散开说明个体差异；多份重抽样均值的散开说明均值不确定性。标准误要从后面这一团算，不能因为都叫标准差就直接替换。'],['偏差比较的是两种中心','将许多重抽统计量取平均，再减原统计量，得到自助偏差估计。它只是替身世界对偏差的近似，不是真偏差被精确揭示，更不能拿单份重抽值减原值当整体偏差。'],['分位区间有适用边界','百分位法从重抽统计量直接取上下分位，操作简单但不总有理想覆盖。严重偏差、边界、偏斜或小样本时需评估别的方法，不能因图看起来平滑就认定95%准确。']],
    '重抽分位覆盖不是自动保证；统计量非规则、样本小或偏差大时，百分位法可能失准，需说明所用区间方法。');
  put('prob-bootstrap-parametric','先拟合一台虚拟机器，再从它生成数据，算哪种重抽？','分开参数bootstrap与直接重抽原样本。',
    '某计数可按泊松模型描述，样本平均为3，就先拟合速率参数3，再从泊松3这个虚拟世界生成与原来同规模的数据，每份重新估参数。与从原始数值里抽签不同，这个世界可能产生原样本没出现过的新计数。但代价是额外相信模型族合适：如果到达会成团，虚拟机器本身就可能搭错。',
    [['参数bootstrap','从拟合的参数分布生成重抽样，再重算统计量。','拟合Pois(3)后从中采样。'],['拟合参数','用原数据给模型旋钮选的估计值。','样本均值3作为泊松λ估计。'],['模型风险','分布族不合适会使模拟不确定性也错。','成团计数未必适合泊松。']],
    'flow',[['原数据拟合','取得λ估计3'],['拟合模型造样本','按Pois(3)抽同样多条'],['每份重新估计','查看估计的波动']],
    '假设计数独立且泊松模型合理；生成新值不等于知道真实总体，模拟仍来自已拟合替身。',
    [['先选择族再估旋钮','需要先提出泊松等参数模型，再用样本估λ。这个选择增加了结构假设，不是非参数抽签法换个按钮；模型是否能描述方差和依赖也要检查。'],['从分布而不是只从名单抽','泊松3模型能产生0、1或更大计数，即使原数据没有某个值。每份重抽样规模与原研究一致，以模仿同样的数据收集量下统计量会怎样改变。'],['重新拟合才能模仿估计','每份都重新算λ或目标统计量，不能只生成数据后仍固定报3。所得波动在拟合模型中有意义，若真实过程不是该模型，重抽再多也不会自动修正。']],
    '参数自助法依赖拟合模型族及采样机制；能生成未见数值不代表修复模型错误或原样本选择偏差。');
  put('prob-bootstrap-null','检验“均值100”，为什么不能直接从均值105的数据抽？','先建立满足零假设的模拟世界，再计算反常程度。',
    '样本平均105，想检验总体平均是否100。若直接重抽，模拟会围着105，而非零假设100，参照世界就错了。某些均值检验可先把每值减5，让替身均值为100，再按规则重抽和计算检验量。重抽是否有效，仍依赖模型与统计量，不能只看是否成功运行。',
    [['零假设模拟','让生成机制满足要检验的假设。','替身中心改为100。'],['中心化平移','从每个值减样本平均，再加假设均值。','xᵢ−105＋100。'],['模拟尾部比例','零假设重抽统计量至少同样反常的份额。','需固定方向与比较统计量。']],
    'flow',[['原样本中心105','不是H₀参照'],['平移到中心100','每个值都减5'],['按规则模拟检验量','再比较尾部反常程度']],
    '均值位置问题的一种零假设重抽示意；并非任何模型或统计量都能靠简单平移实现有效检验。',
    [['区间模拟与检验参照不同','普通重抽围绕当前经验分布，可用于估计抽样波动；检验则要问若H₀成立时会怎样。当前平均105不满足100，不能不调整就把同一模拟分布贴上零假设标签。'],['平移只改变需要约束的中心','将每值改为xᵢ−105＋100，经验中心成为100，而相对偏差保留。此构造针对均值位置模型；若假设关于方差、独立或复杂结构，所需模拟约束会不同。'],['用预定统计量比较','每份重抽都计算相应检验量，再累计至少眼前这么极端的比例。原始均值、中心化差值和学生化统计量不能随意混用，单侧双侧规则也应在前面确定。']],
    '零假设构造要与问题匹配；平移法不是通用检验配方，bootstrap有效性及有限模拟p值计算需另外检查。');
  put('prob-bootstrap-limits','重抽一百万次，为什么还可能错得很稳定？','区分模拟精度与原样本代表性、依赖和统计有效性。',
    '用五位熟人的作息估全校，再从五人中重抽一百万次，仍看不到被排除的人群。样本里没出现事故，重抽也永远没事故；样本最大值为9，普通重抽最大值也不可能超过9。重抽次数多能让计算更稳定，却不能保证替身总体足够像真总体。稳定的错误不比不稳定的错误更可靠。',
    [['模拟误差','重抽次数有限带来的数值波动。','增加B可使分位估计较稳定。'],['统计误差 / 偏差','原样本与目标总体之间的信息限制。','熟人样本遗漏其他人群。'],['重抽单位','应该一起保留的独立或依赖结构单元。','同一人的多次记录不能乱拆。']],
    'compare',[['增加重抽次数B','改善模拟稳定性'],['不增加原信息','未见事故仍未见'],['检查抽样与目标','端点和依赖可能失效']],
    '普通经验重抽不会超出已有取值；端点统计、稀有事件及相关数据可能需要专门方法。',
    [['先检查最初五人代表谁','有选择偏差的数据无论怎样重复抽签，支持的仍是那五个人显示的世界。增加模拟次数不是扩大真实样本，也不能把熟人调查自动变成全校随机抽样。'],['再看替身能否产生关键情况','若目标依赖真实分布右端，重抽最大值被原最大值封顶，可能模拟错关键尾部行为。零事故同样不证明真风险为零，不能让重抽的零波动冒充确定性。'],['最后才调计算次数','时间相关数据可能需要分块，同人多次需尊重分组，非规则统计量也需特别处理。地基检查通过后，再增大B减模拟误差；否则只会把搭错的世界算得更精细。']],
    '普通bootstrap有模型、抽样与统计量条件；专门重抽或参数模型也需新增假设，更多B不能通用修复。');
  put('prob-r-basics','一行R代码，怎样翻译成“把什么交给哪个工具”？','按数据、命名、动作和输出逐步读最小脚本。',
    'x <- c(2,4,6)读成“把三数合成一列，存为x”；mean(x)读成“把x交给平均工具”。不用一口气背英文，先说明输入、动作和输出单位。R会替你算，却不知道数据是否代表总体，也不会自动识别秒误记为分钟；先用小数据手算核对。',
    [['向量 c(...)','将一组值连接成一列对象。','c(2,4,6)有三项。'],['赋值 <-','把右边结果保存到左边名字。','x <- ...不是数学比较。'],['函数 mean(...)','括号里给输入，函数按规定产生输出。','mean(x)应得到4。']],
    'flow',[['准备三个数','2、4、6'],['命名为x','保存一整列数据'],['交给mean','输出平均4']],
    '最小R脚本的计算流程，网页讲解不等于执行R；实际运行需相应R环境。',
    [['先用手算确定锚点','2＋4＋6＝12，除3为4。先知道这个答案，再看软件输出，可以识别数据漏录或代码没重新运行等错误；运行成功只说明语法通过，不等于统计问题选对。'],['符号按动作读','c把值连成向量，<-把右边对象交给左名，mean把向量变成一个平均。R下标通常从1开始，和C数组从0开始不同，别把两门语言约定混在一起。'],['缺失不是自动的零','若结果含NA，应检查缺失记录；na.rm选项可以在计算时剔除，却不能证明删除不产生偏差。输入单位、样本量和观察对应关系仍需要人核查。']],
    '网页提供代码点读，不实际执行R；NA处理、对象类型与版本约定需检查，软件不会替你修复抽样或单位错误。');
  put('prob-r-boxplot','箱子外面的点，软件是在命令我删掉它吗？','读懂R箱线图的箱、须与远点规则。',
    '等待时间1、2、3、4、20分钟里，20会把平均拉高，也可能被箱线规则标成远点。它可能是录入错误，也可能是真实的一次紧急事件，图形本身分不清。R箱线图把中间范围和较远观察压缩展示，标点是提醒核查，不是删数据裁判。先查单位与原记录，再决定是否需要纠正或保留。',
    [['中位数 / 铰链','排序后的中间位置与箱体两侧位置。','R铰链可能与默认分位算法略异。'],['IQR','上、下四分位位置之差，描述中间散开。','常用1.5倍IQR作须线规则。'],['须 / 远点','须延到规则内最远观察，超出者单独标点。','不一定延到全体最小最大值。']],
    'flow',[['先按规则画图','箱、须、远点'],['把远点追回记录','查20的单位与来源'],['依据事实处理','真事件保留，录错纠正']],
    'R默认箱线图描述规则的核查流程；图上远点不等于错误，也不自动表示正态模型被证伪。',
    [['中线不是自动等于平均','箱内横线通常是中位数，中间箱长由铰链决定。对偏斜数据，均值可能远离中位数，所以不能把图里每个水平位置都用“平均”来称呼。'],['须落在实际观察上','默认须通常到仍在箱外1.5倍箱长以内的最远观测，而不是必定画在理论边界上。超出规则的点只是描述性标记，是否有错误需回到原测量。'],['保留处理依据','若20原来是秒，应按证据纠正单位；若真实等待20分钟，它可能正是风险研究所关心的尾部。删掉让图好看会改变目标，应记录核查过程而不是照点删行。']],
    '小样本铰链与分位算法可不同；箱线图压缩了形状，远点删除须有测量或设计依据，不能只为显著或对称。');
  put('prob-r-test','t.test打印很多行，哪行说的是差异，哪行说的是证据？','让软件输出逐项对应研究问题。',
    '输入9、10、11、12并检验均值是否10，R返回估计、统计量、自由度、p值和区间。均值10.5是当前结果，p值评估假设下反常，区间描述推断不确定性。只盯p会漏掉单位、方向和差异大小，甚至不知运行的是配对还是独立组检验。',
    [['mu / alternative','指定待检均值及检验方向的参数。','mu=10，方向须预定。'],['estimate / statistic','点估计与经标准误校准的差异。','平均10.5，t约0.775。'],['p.value / conf.int','尾部p值与相应置信区间。','不是参数真假概率。']],
    'flow',[['先定问题','均值是否10？'],['输入正确设计','单样本、配对或独立'],['逐项读输出','估计、区间、统计量、p']],
    '9、10、11、12的单样本示例；t自由度3，精确解释依独立正态等条件。',
    [['先验证可手算部分','四数平均10.5，样本方差5/3，标准误√(5/12)，t为0.5除标准误，约0.775。先核这几项，能发现mu误填0或少录一行等输入问题。'],['方法名也要读','R两独立组t.test默认常用Welch，不默认等方差；paired设置需要真实逐人对应。软件只能按参数执行，不知道你两列第一行是不是同一个人。'],['把结果写回问题','报告差多少单位、区间多宽、哪种方向和模型下得到p值。未拒绝不证明均值恰为10，小样本信息可能不足；p不能取代差异的实际意义。']],
    '精确t结论有样本条件；软件默认值不证明设计正确，尤其配对、等方差及单侧方向都必须由研究确定。');
  put('prob-r-anova','表里写Df和Mean Sq，能否翻成刚才的平方账？','把R方差分析输出与信号噪声计算对应。',
    '在R里写y ~ group，可以读成“用组别解释数值y”。组别要当类别，而不是随便写成1、2、3后让软件画一条连续趋势。aov的表把平方和除自由度得到均方，再用组间均方除组内均方形成F。英文列名只是原来那本平方账的缩写，读懂来路比记住它们在第几列更有用。',
    [['factor / group','factor声明类别，group保存组别。','A、B、C不是有等距含义的数轴。'],['Df / Sum Sq','自由度与平方和的英文列名。','总账与可变方向数。'],['Mean Sq / F value','均方与均方比。','平方和先除自由度，再相除。']],
    'flow',[['声明组别类别','factor而非连续组号'],['拟合组别模型','y ~ group'],['读平方账表','SS/df→MS→F']],
    '单因素有截距模型的R读法；~是建模公式分隔符，不是约等号，也不补齐误差条件。',
    [['组号类型会改变模型','把三组当数值1、2、3，可能只拟合随组号的直线变化；转为因子才允许各组有独立均值水平。代码没有报错，也可能已经换了研究问题。'],['从平方和读到比值','Df表示自由度，Sum Sq表示平方和，相除为Mean Sq。组间Mean Sq再除残差Mean Sq得到F，Pr(>F)是相应参照右尾概率，不是组均值相等的后验机会。'],['整体拒绝不等于三组全不同','即使表中p很小，也仅排除共同均值假设。还需看各组估计、误差与适当多重比较，不能把样本均值最大者自动宣布为最优方法。']],
    '经典ANOVA依独立、正态、等方差等条件；类型与公式会影响模型，显著表格不自动补齐设计或因果依据。');
  put('prob-r-regression','lm拟出一条线，coef、fitted、residuals分别拿到什么？','按模型、拟合值、残差与预测对象阅读R回归。',
    'lm(y ~ x)把学习小时与分数拟成模型。coef取系数，fitted取拟合均值，residuals取实际减拟合值。predict还要区分人群平均与新个人：同一条线能回答多个问题，运行成功不说明取对了量，先把输出翻译成研究对象。',
    [['lm(y ~ x)','按指定公式拟合线性模型的R函数。','默认包含截距。'],['coef / residuals','模型系数 / 观察减拟合的残差。','残差不是未知真实误差本身。'],['predict的区间类型','confidence针对均值，prediction针对新观察。','后者通常更宽。']],
    'flow',[['输入x与y','行必须对应同一观察'],['拟合模型对象','lm保存系数和其他信息'],['按问题提取','系数、残差或预测区间']],
    '普通线性回归的R操作对应图；R²高或系数显著均不直接证明因果及模型真实。',
    [['先确认每行确实是一对','若一列小时来自甲同学、一列分数错对成乙同学，模型仍能拟合，但关系已经失真。整理对应、单位和缺失，比急着解释系数更先。'],['三个输出不是三个同义词','coef是整条线的参数估计，fitted是每个给定x上的预测均值，residuals是每个实际y减该均值。不能把一列残差当成新个人的预测分数。'],['预测区间先选对象','给新x时，问平均用confidence，问新观察用prediction。样本外x可能是危险外推；即使predict照样返回一行数，也要先判断线性关系是否在这段范围可信。']],
    '推断区间依线性误差条件，外推有额外模型风险；软件系数是条件关联，不能单凭输出证明因果。');
  put('prob-r-bootstrap','sample(...,replace=TRUE)里，每个选项在模仿什么？','把R重抽代码逐步对应经验世界与统计动作。',
    'x保存2、4、9，sample有放回抽三项，再用mean求新平均，重复后得到自助均值分布。replace=FALSE若无放回抽满三项，只是打乱顺序，平均永远不变。一个选项就能把“模仿换样本”改成“重排同一批”，所以括号里的动作也要读清。',
    [['sample','按指定规则抽取元素的R函数。','抽样对象和数量都要明确。'],['replace=TRUE','抽后放回，允许同一元素重复。','可能抽成2、2、9。'],['replicate / set.seed','重复动作 / 设置随机生成起点。','种子帮助复查但不增加样本信息。']],
    'flow',[['从x放回抽','数量仍为length(x)'],['新样本求mean','每次得到一个均值'],['重复并汇总','看sd或分位数']],
    '普通独立样本均值bootstrap代码映射；网页不执行R，实际运行与随机版本约定另需记录。',
    [['抽样设置决定模拟实验','样本量取length(x)保持与原来相同，replace=TRUE允许重复。若无放回抽满三项，只是排列，均值不变，不能拿零波动说明原平均无误差。'],['重复的是整个统计动作','每轮都要重新抽，再重新求mean，最后收集许多均值。若只把原mean反复复制，数组虽变长，却没有生成任何新模拟；从动作层读括号能发现这种错误。'],['记录随机性与模型限制','设置种子便于同环境复查，但不同版本与随机算法可能不同。重抽标准差估计的是均值标准误，且普通方法仍需代表性、独立和合适统计量条件。']],
    '代码复现不等于统计有效；普通逐项放回重抽不适合所有相关数据，种子与增加重复次数也不修复抽样偏差。');
  window.PLAIN_BEGINNER = Object.assign(window.PLAIN_BEGINNER || {}, data);
})();
(() => {
  const data = {};
  const put = (id, plainTitle, goal, story, terms, kind, nodes, caption, steps, boundary) => { data[id] = {plainTitle,goal,story,terms:terms.map(([word,meaning,example])=>({word,meaning,example})),diagram:{kind,nodes:nodes.map(([name,detail])=>({name,detail})),caption},steps:steps.map(([title,text])=>({title,text})),boundary}; };
  put('prob-random-sample','三个人的数据，怎样变成一个会波动的平均？','分清总体、一次样本与由样本算出的统计量。',
    '学校想知道全体同学平均睡眠时间，不可能每次都问所有人，于是按规则抽三人。抽之前，三人的数值还未知；抽之后得到7、8、6小时，算出平均7。下次换一批可能得到别的平均。统计量就是按固定规则从一份样本算出的数，而它在重复抽样时也有自己的变化规律。',
    [['总体','想了解的完整对象集合或其数值分布。','全校同学的睡眠情况。'],['随机样本','按模型抽得的一组观察值，经典模型常要求独立同分布。','X₁、X₂、X₃。'],['统计量','只用样本数据和已知规则计算的量，不含未知参数。','三人样本平均。']],
    'flow',[['总体','目标：全校平均'],['抽到一批','7、8、6小时'],['按规则计算','平均7小时']],
    '一次三人样本用于说明统计量的形成；代表性和独立同分布不能只由“有三条记录”推出。',
    [['总体问题先写清','要了解全校平均，就不能只问愿意回消息的三个晚睡同学，再把便利记录冒充随机样本。抽取机制影响你能推广到哪里，计算平均本身不会修复偏选。'],['一份数据与抽样变量不同','抽前X₁等是会随抽样变化的变量；抽后7、8、6是已实现的数据。固定算法给出平均7，描述这一份样本，不表示总体均值已经准确知道。'],['统计量也有分布','重复同样抽样，每批平均可能变化，形成平均的抽样分布。估计误差、置信区间和检验随后都在使用这份变化规律，而不是只盯着当前这一个7。']],
    '三条记录仅作演示；独立同分布、抽样代表性及有限总体修正等条件需按实际设计确认。');
  put('prob-hist-box','两个平均都为5，数据会不会完全不同？','先用分布形状与分位位置检查平均隐藏的信息。',
    '一组数据是4、5、6，另一组是0、5、10，两组平均都是5，分散程度却差很多。再多些数据时，直方图把相邻数值归进区间，看哪里集中、哪里长尾；箱线图用中间位置和四分位数作压缩摘要。图不是平均的装饰，而是检查单个数字省掉了哪些重要差异。',
    [['直方图','按数值区间分组展示频数或密度的图。','等宽柱比较各段人数。'],['四分位数','把排序数据按约四等份切开的数值位置。','中间50%位于第一与第三四分位间。'],['箱线图','用中位数、四分位及规则须线概括数据。','远处点是进一步检查线索。']],
    'compare',[['第一组','4、5、6：紧凑'],['第二组','0、5、10：分散'],['同一个平均','两组都为5']],
    '小组例子只比较中心与散开；实际箱线图分位算法、须线规则和直方图区间都应说明。',
    [['先看原数据或整体形状','两组均值相同，不代表观测分布相同。先列数据发现第二组更分散；更大数据可画直方图，检查偏斜、多个峰或长尾，避免平均把不同群体揉成一种。'],['箱子保留中间一半','箱线图的箱体表示约中间50%的排序范围，中线是中位数，不是自动等于均值。须线和离群点按具体规则生成，不能只凭点画在外面就判作错误。'],['画法会影响眼睛判断','直方图分组宽度改变，形状也会变；不等宽柱应按面积读频率或使用密度尺度。图是探索证据，要连同样本量和绘图规则一起看，不能凭视觉即确认分布模型。']],
    '少量示例不支持分布诊断；分位算法可不同，箱外点不自动异常，直方图柱高在不等宽时不能直接当概率。');
  put('prob-chi-square','几个标准化偏差平方加起来，为何成为一把尺？','知道χ²变量从何而来，并连接正态样本方差。',
    '把几个互相独立的标准正态误差各自平方，再加起来，得到一个不为负、通常偏向右边的量。它的大小说明这批标准化偏差合起来有多大，这类量叫χ²变量。正态样本的方差也能通过缩放接到这把尺上；用了样本平均定位中心后，能独立摆动的方向少一个，所以会出现n−1。',
    [['χ²（卡方）分布','若干独立标准正态变量平方和的分布。','Z₁²＋Z₂²服从自由度2的χ²。'],['自由度','构成该随机量的独立变化方向数。','用样本均值后偏差和为0，少一维。'],['样本方差 S²','围绕样本平均的平方偏差和除以n−1。','正态时(n−1)S²/σ²有χ²尺。']],
    'flow',[['独立标准正态','各项中心0、尺度1'],['分别平方再加','非负的总偏差'],['用χ²衡量','自由度随独立项数定']],
    '定义图的标准正态项须独立；与样本方差的精确连接还依赖独立正态样本。',
    [['平方保留大小而不抵消','一项为−2，平方为4；另一项为1，平方为1，加起来为5。负偏差不会抵掉正偏差，但这个数是否可用χ²标定，要先检查来源是不是独立标准正态。'],['自由度不是机械样本数','若直接加k个独立标准正态平方，自由度为k。样本偏差先减了共同样本平均后，偏差和固定为0，所以n个偏差只有n−1个独立方向，不能混为同一计数。'],['方差推断要用整体缩放','在正态独立样本下，(n−1)S²/σ²能对上χ²分布。S²是这批估出的方差，σ²是总体未知方差；分子分母职责不同，之后可用这份已知分布作区间或检验。']],
    'χ²精确方差推断依赖正态与独立等条件；一般非正态数据的样本方差不能未经检查直接套同一分布。');
  put('prob-t-f','分母也是估出来的，为什么尺子要更宽？','区分t标准化均值与F方差比的随机来源。',
    '若总体波动尺度已知，平均偏离中心几个标准误可以用标准正态衡量；但通常这个尺度也由同一批样本估计，分母会抖动，极端比值更容易出现，t分布因此比正态留更厚尾部。若比较两份独立方差，把各自校准后的平方量相除，形成另一把F尺。两个名字对应不同的随机比值。',
    [['t分布','独立标准正态除以标准化χ²平方根得到的比值分布。','正态样本均值用S作尺度会得到t。'],['F分布','两个独立χ²量各除自由度后再相除的分布。','常用于相应方差比或均方比。'],['自由度','决定这些尺子形状的独立变化数。','小自由度t尾部更厚。']],
    'compare',[['尺度σ已知','均值用Z尺'],['尺度改用S估计','额外波动→t尺'],['两个平方量相除','各自除自由度→F尺']],
    '图示经典正态独立条件下的统计量来源；并不是把任意分母换成样本量都会得到t或F。',
    [['先看分母来自哪里','总体σ已知时，标准误σ/√n是固定尺度；用样本S代替后，分子分母都随这批数据变化。t尺正是把这种不确定性纳入，而不是只给Z改个字母。'],['F需要两份合适平方量','F不是随便两个数的比，而是两份独立χ²量分别除以各自自由度后的比。方差分析中的F连接也依赖模型，使分子分母具备所需尺度与独立关系。'],['先检查条件再查临界值','正态样本均值t统计量自由度通常n−1，F有分子与分母两个自由度，交换方差次序会改变问题。软件报出的分布名不替你证明数据条件正确。']],
    '精确t、F结论有正态与独立结构前提；F有两个自由度且比值方向重要，不能把任意统计比值当成这些分布。');
  put('prob-order-statistics','最小那一个，也会随换样本而变吗？','把排序后的第几项看成新的统计量。',
    '每次抽三件产品测寿命，排成从短到长。第一件是谁、最短寿命多少，都可能随下一批改变，所以最小值、最大值、中位位置也各有抽样分布。问最小值超过五小时，等于三件全都超过；问最大值不超过五小时，等于三件全都不超过。排序把记录位置换成名次，但没有消除随机性。',
    [['次序统计量 X_(k)','将一批数据排序后第k个值。','X_(1)为最小，X_(n)为最大。'],['抽样分布','统计量在重复同样抽样时的概率规律。','每批最小寿命仍会变化。'],['独立同分布','各观察相互独立且遵循同一分布。','才能把全体阈值概率写成同一幂。']],
    'flow',[['一批三件','寿命7、4、6'],['从小到大排','4、6、7'],['留下排序位置','最小4，最大7']],
    '数值仅演示排序；推导最值抽样分布时要回到未排序观察的联合条件。',
    [['编号与名次不要混','原第三件寿命6，排序后却在第二位。X₃指原记录编号，X_(3)指排好后的第三小；括号表达名次，不是重新独立抽了一件。'],['翻译最值阈值','最小值大于5，要求每件寿命都大于5；独立同分布时若单件超过概率q，三件同时超过为q³。这里排序后的值本身通常不独立，不能拿它们再假设独立。'],['中间名次也能数事件','第2小不超过5，等于至少两件不超过5，可转为成功计数问题。先把名次条件翻成人数条件，再用适合的分布，比盲背每个名次密度更清楚。']],
    '排序统计量之间通常相关；最值幂式与二项计数翻译需原样本独立同分布，连续公式还要注意重复值。');
  put('prob-moments','样本平均，怎样反推模型里的未知旋钮？','用样本特征对接总体特征，再解出参数。',
    '指数模型里平均等待是速率λ的倒数。样本平均五分钟，就把模型平均1/λ与五对接，得到λ估计每分钟0.2。这不表示每次都等五分钟，而是用样本特征校准模型旋钮。矩估计先问模型特征怎样由参数决定，再用样本给出替代值。',
    [['矩估计','用样本矩替代总体矩，解相应参数方程。','令样本平均等于模型均值。'],['参数λ','指数模型的速率，单位为每单位时间。','平均5分钟对应速率0.2/分钟。'],['样本矩','样本取值幂的平均，用来描述数据特征。','一阶样本矩就是样本平均。']],
    'flow',[['模型给关系','平均＝1/λ'],['数据给平均','观察均值5分钟'],['对接并求解','λ估计＝1/5']],
    '假定指数模型且均值存在；方程解是由当前样本得到的估计，不是真参数已被准确测出。',
    [['先找模型与参数的桥','不能直接拿5当λ，因为模型里平均等待是1/λ，而λ单位为每分钟。先写清总体矩与参数关系，才能知道数据的平均要对接哪个表达式。'],['用样本特征建立方程','本批平均为5，于是用1/λ≈5建立估计方程，解得0.2。用约等号提醒这是把未知总体特征换成有抽样波动的样本特征，并非逻辑恒等。'],['检查解的范围与唯一性','指数速率应为正，当前解符合；一般矩方程可能无解、多解或跑出合法参数空间。计算解只是中间步骤，还要检验模型与参数约束，不能自动接受任何代数结果。']],
    '矩估计依赖所选矩存在及模型关系正确；解可能不唯一或不合法，也不自动具备无偏、最小方差等全部好性质。');
  put('prob-mle','已经看到三次成功一次失败，哪个成功率更说得通？','把数据固定，比较不同参数解释这份数据的程度。',
    '四次独立试验看到三次成功、一次失败。固定记录，分别假设成功率为0.2、0.5、0.75，比较记录有多容易出现。最大似然挑最有利于当前数据的参数，本例为0.75。它在固定数据后比较参数，不给参数本身分配概率，也不保证估计就是真值。',
    [['似然 L(p)','数据固定时，作为参数p函数来看的模型概率或密度。','有序记录的似然为p³(1−p)。'],['最大似然估计','在合法参数范围中让似然最大的参数值。','三成一败给估计p＝3/4。'],['对数似然','取似然的对数，保留最大值位置便于计算。','乘积可化成加法。']],
    'flow',[['固定数据','成功、成功、成功、失败'],['改变假设p','比较p³(1−p)'],['找最有利p','本例最大在0.75']],
    '独立同成功率伯努利模型；图比较参数对这份记录的解释，不是参数的后验概率图。',
    [['先固定已观察的那份记录','数据不随这一步比较改变，我们只改变模型参数p。四次独立，三次成功贡献p³，一次失败贡献1−p；若记录只保留次数，还会有组合因子但不改变此例最大位置。'],['在合法范围内寻找最大','p必须在0到1之间，不能任意挑实数。比较或求导可找到p＝0.75；边界也要检查，因为全成功等数据的最大值可能就在参数边界，而不在内部驻点。'],['选出估计后仍有抽样误差','换一批四次试验，成功数可能变，估计也会变。最大似然没有自动消除小样本偏差，更不能把似然值当作“这个参数为真的概率”，两者条件方向不同。']],
    '结论依赖独立同成功率模型；连续数据使用密度形成似然，单点概率为零不妨碍比较密度似然。');
  put('prob-censored-mle','试验结束时还没坏的产品，能直接删掉吗？','让未观察到具体失效时间的产品也贡献生存信息。',
    '测试三件产品，观察到2小时、4小时失效，第三件到5小时试验结束仍没坏。第三件寿命未知，但不是没有信息：至少超过5小时。若只留下前两件，就把耐用产品系统性删掉。截尾似然让已失效者贡献具体失效信息，让未失效者贡献“活过观察截止”的机会，两种记录要分开处理。',
    [['右删失 / 截尾记录','只知道寿命大于某截止时间，未见完整失效时刻。','第三件T>5。'],['生存函数 S(t)','寿命超过t的概率。','S(5)＝P(T>5)。'],['似然贡献','一条记录在模型下提供的概率或密度因子。','未失效者用S(5)，非f(5)。']],
    'compare',[['已坏产品一','在2小时观察到失效'],['已坏产品二','在4小时观察到失效'],['仍未坏产品','只知道寿命>5']],
    '固定截止的右删失例子；未坏不等于恰在截止时坏，也不能当作没有样本。',
    [['先区分完整与不完整记录','前两件有具体失效时间，第三件只知道超过5。把它填成寿命5会假装在截止时失效，直接丢弃则漏掉长寿信息；两种处理都会改变数据含义。'],['按记录内容写对应因子','连续寿命模型下，已失效者通常贡献失效密度；只知T>5者贡献尾概率S(5)。整个似然把合适因子组合，而不是所有行一律套同一种密度值。'],['观察机制也需要说明','若统一到5小时停试，是一类清楚的设计；若产品快坏时更容易失联，删失机制会带额外信息，不能还当作与寿命无关。估计前先交代试验怎样结束与谁被观察到。']],
    '例子是固定截止的右删失；教材不同“截尾”术语约定应核对，若删失与寿命信息相关，普通似然形式需调整。');
  put('prob-estimator-criteria','估计器总瞄准靶心，就一定更好吗？','同时看偏差、波动、均方误差与样本增多后的稳定性。',
    '两位投手瞄准靶心：甲平均位置正中，却每次散得很开；乙总偏一点，但落点紧密。估计器也要分开看平均是否偏、换样本会抖多大。均方误差把两种代价合起来；相合则问样本越来越多时是否靠近真值。无偏只是其中一条性质，不能单凭这个好听的词就选出所有场景最好的方法。',
    [['偏差 / 无偏','估计值的重复抽样平均与真参数之差；差为0称无偏。','瞄准平均不等于每发都准。'],['均方误差 MSE','估计与真值之差平方的平均。','MSE＝方差＋偏差²。'],['相合','样本量增大时估计按相应意义趋近真参数。','大样本逐渐稳定，不保证小样本无偏。']],
    'compare',[['平均偏哪里','偏差描述靶心偏移'],['每次散多开','方差描述抽样波动'],['总体平方误差','两项合成MSE']],
    '靶图比较的是重复抽样性能；不同评判准则与损失目标可能选出不同估计器。',
    [['无偏看的是很多次平均','一个无偏估计器这次仍可能离真值很远，因为无偏只要求重复抽样平均对准。若方差很大，它会经常产生很不稳定的结果，不能把平均准确翻成单次保证。'],['平方误差把两项一起算','在相应矩存在时，MSE等于方差加偏差平方。适当引入一点偏差若明显减小波动，可能使总体平方误差更小，这解释了有偏方法也可能值得使用。'],['相合再增加样本量维度','相合关心n逐渐增大时的行为，不只比较固定n的一张靶图。无偏不自动相合，相合也不要求每个有限样本量无偏；结论要按各自定义分别验证。']],
    '这些指标需相应期望存在；“最佳”还依损失函数、参数范围和样本量，单一性质不能替代完整比较。');
  put('prob-confidence-meaning','95%说的是参数，还是造区间的方法？','把置信度理解为重复抽样区间程序的覆盖率。',
    '同一台机器的真实均值固定不动，我们反复抽样，每批都按同一规则造一段区间。区间会随数据左右移动，其中大约95%的区间能盖住真均值，这就是95%置信程序的含义。当前这一段算完后，要么盖住要么没盖住；频率学派通常不把固定参数说成有95%机会在已固定区间里。',
    [['置信区间','由随机样本构造、用于覆盖未知固定参数的区间。','不同批样本给不同端点。'],['置信水平95%','相应模型下，区间程序在重复抽样中的覆盖比例。','长期约95%的区间盖住真值。'],['参数 / 统计量','参数固定未知；样本统计量随抽样变化。','真均值固定，区间端点随机。']],
    'compare',[['固定真均值','同一条竖线'],['重复抽样区间','每批端点会移动'],['长期覆盖','程序约95%盖住竖线']],
    '图中的随机对象是区间；95%覆盖保证依赖所用抽样模型和构造方法。',
    [['先分谁动谁不动','真均值是同一总体参数，不随抽哪批数据改变；样本平均和区间端点会变。把真值画成固定竖线、每批区间画成横条，有助于看清覆盖率究竟统计哪一类随机变化。'],['把95%读成程序性质','想象重复用同一个方法造很多区间，约95%能罩住固定真值。它不保证当前区间必罩住，也不说95%的原始观测都落在其中，后者是另一种范围问题。'],['算完一段后谨慎表达','可说“按该模型和方法得到95%置信区间”，避免把它改成参数的后验概率。如果需要给参数本身分配概率，要另建先验与后验框架，不能偷换统计解释。']],
    '覆盖率依赖模型、抽样与所用方法；选模型或挑区间的额外步骤可能改变实际覆盖，近似区间也不保证精确95%。');
  put('prob-normal-mean-ci','估平均时，为什么知道σ和不知道σ要换尺？','分开单件波动、平均标准误以及Z与t临界值。',
    '抽25次测量，平均为10。若总体标准差已知为5，平均的标准误是5除以根号25，等于1，可围着10加减相应Z倍数。若5只是这批估出的标准差，分母也会波动，正态样本下应换成t尺，并用24个自由度。相似的区间外形，背后是不同的不确定性来源。',
    [['标准误','估计量在重复抽样中的标准差。','已知σ时，平均标准误σ/√n。'],['Z区间 / t区间','尺度已知用正态尺，尺度以S估计时在正态模型下用t尺。','n＝25时t自由度24。'],['误差边际','临界倍数乘标准误，决定区间半宽。','不是把单件标准差直接加到平均。']],
    'compare',[['总体σ已知为5','标准误5/√25＝1'],['只知样本S＝5','用t尺，自由度24'],['区间围着平均10','半宽＝临界值×标准误']],
    '独立正态测量模型；图分支按σ是否真正已知，而非数字5看起来相同就认为等价。',
    [['先把单件尺度换成平均尺度','每件标准差5，不等于25件平均的标准差5。独立同分布时平均尺度为5/5＝1；样本量出现在根号下，不能错用5/25。'],['再核对尺度是否由样本估计','若总体σ真正已知，用相应正态临界值；若只有样本S，精确正态均值程序用t临界值。两种输入同写5，也不能抹掉“已知”与“估计”差别。'],['最后解释区间对象','把临界值乘1得到半宽，围着样本平均10造区间。这是总体均值的区间，不是让95%的未来单件值都落入；预测单个值还要加入单件波动。']],
    '精确小样本t区间依赖独立正态模型；非正态大样本可能近似适用，σ是否已知也必须有实际依据。');
  put('prob-normal-variance-ci','想知道波动多大，为什么不能围着S²简单加减？','借χ²关系给总体方差造区间，并注意倒数翻转边界。',
    '同样平均10，两台机器一台很稳、一台忽高忽低。现在目标不是平均，而是总体方差σ²。正态样本下，(n−1)S²除以σ²有一把已知χ²尺；把χ²中间的概率范围反解回σ²，就得到方差区间。因为未知量在分母，反解时上下界互换，所以区间通常不是围着S²对称加减。',
    [['总体方差σ²','总体围绕均值的平方波动参数。','单位是原测量单位平方。'],['χ²枢轴量','分布已知但含未知参数、可用于反解的组合。','(n−1)S²/σ²。'],['分位数','使累计概率达到指定比例的χ²阈值。','较大分位数放在区间下界分母。']],
    'flow',[['样本给出波动','计算(n−1)S²'],['χ²给两个门槛','小门槛a，大门槛b'],['反解总体方差','总量/b ≤ σ² ≤ 总量/a']],
    '独立正态样本，a、b为正χ²分位数；倒数让大小门槛换边，区间一般不对称。',
    [['先认清待估对象','S²是当前样本给出的波动，σ²是总体参数。不能把S²当作已知真方差来省掉推断，也不能用均值的t区间替代方差区间，因为它们研究的随机量不同。'],['使用χ²的中间概率范围','正态独立样本下，把(n−1)S²/σ²夹在相应χ²分位数之间，能获得所需覆盖程序。自由度是n−1，表里分位数对应的是累计概率方向，要先检查。'],['反解时检查大小顺序','若a≤C/σ²≤b且C为正，就得到C/b≤σ²≤C/a。大分位数在下界分母。若想要标准差区间，最后再对两端开平方，别把方差单位直接改成原单位。']],
    '精确χ²方差区间对正态假设敏感；一般非正态数据不能仅凭样本量看着够多就直接当作精确区间。');
  put('prob-two-normal-ci','两组平均差，先问是两批人还是同一批人？','按独立与配对设计选择差值区间，并谨慎处理等方差假设。',
    '比较两种训练方法，可以各抽一批不同学生，也可以让同一批人训练前后各测一次。前者要估两组均值之差，后者要先算每个人自己的前后差；人的基线差异因此不再混进效果。两独立组也不能看到样本标准差接近，就自动宣布总体方差相等并合并。先看设计，再挑公式。',
    [['独立两样本','两批观察按设计相互独立，各代表一个总体。','不同学生分别用甲乙方法。'],['配对差值','有对应关系的两次记录先逐对相减。','同一个人的训练后减训练前。'],['Welch / 合并方差','前者不假设两总体等方差；后者需等方差前提。','不能只因n相同就合并。']],
    'branches',[['不同两批人','两独立均值之差'],['同一批人前后','先构造每人差值'],['再看尺度前提','Welch或合法的合并方差']],
    '选择路径由研究设计与模型条件决定；配对不是把两份无关列表按行硬凑。',
    [['配对先保留对应关系','甲同学前后两次应相减，乙同学也相减，得到一组差值。之后对差值均值推断，关注的是同一人的变化；忽略配对会丢掉数据中重要的共同基线。'],['独立组用各自波动合成','两组独立时，均值差的方差来自两组平均方差相加。未知且不等的总体方差可用Welch路径；等方差合并方法需要额外前提，不能由习惯自动添加。'],['区间仍然针对总体差','区间包含0表示在相应方法下零差未被排除，不证明两方法完全一样。区间宽度、样本量和有意义差异大小也要读，不能只看0在不在。']],
    '配对需真实对应，独立组需设计支持独立；正态、等方差和近似条件各自检查，含0不等于证明无差异。');
  put('prob-proportion-ci','问100人有60人同意，60%到底有多准？','把样本比例与总体成功率分开，并识别小样本区间局限。',
    '抽100人有60人同意，样本比例0.6。换一批比例会变，所以还要给总体同意率的不确定范围。近似常用√[p(1−p)/n]描述波动，但p未知要估；样本很小或全同意时，简单对称区间可能很差，不能见到百分数就套同一式子。',
    [['样本比例 p̂','样本中成功人数除以总人数。','60/100＝0.6。'],['总体比例p','目标人群真正的成功机会，未知参数。','不是当前100人的固定百分数。'],['比例标准误','描述样本比例重复抽样波动的尺度。','近似用√[p̂(1−p̂)/n]。']],
    'flow',[['抽到100人','60人同意'],['估比例0.6','不同样本会改变'],['评估波动与区间','方法需检查边界表现']],
    '独立伯努利式抽样的入门模型；区间方法还应考虑复杂抽样、有限总体和边界情形。',
    [['先分固定数据与未知目标','这份数据的0.6已经确定，未知的是总体p。置信区间是在评估从这份样本推总体的误差，不是说60位同意者的人数本身还会在当前表里改变。'],['误差随成功率和样本量变','独立同分布模型下比例方差为p(1−p)/n。p接近一半时波动较大，样本越多尺度通常越小；不能用任何比例都相同的固定百分之几作通用误差。'],['少数或全成功需换审慎方法','简单Wald对称近似在小样本、极端比例时可越过0或1，覆盖也差。Wilson或精确二项等方法各有约定，应该按情形选择，不把简单式子当作默认保证。']],
    '示意依独立同概率模型；抽样偏差不会被区间自动修复，小样本或接近0/1时应检查方法而非只套对称近似。');
  put('prob-one-sided-ci','只关心是否太高，为什么还要两边都留余地？','用单侧界表达研究真正需要的安全方向。',
    '工厂只担心污染均值太高，想给出一个可靠上界；研究收益则可能只关心最低能保证到哪里，想要下界。单侧区间把覆盖目标集中在一个方向，不是把双侧95%区间随意剪掉一半。方向应由问题事先决定，不能看完数据哪边漂亮，就改成那一侧来增加显著机会。',
    [['上置信界U','造出使固定参数不超过U的相应覆盖程序。','均值≤U，另一侧不设有限界。'],['下置信界L','造出使固定参数不小于L的相应覆盖程序。','均值≥L。'],['单侧分位数','把允许漏盖的概率放在一个方向的阈值。','95%单侧用0.95方向，不是0.975。']],
    'compare',[['怕污染太高','需要一个上界'],['关心最低收益','需要一个下界'],['先确定方向','再选择相应临界值']],
    '单侧目标由研究问题指定；同一置信水平下的分位数分配与双侧区间不同。',
    [['把实际关心写成方向','污染问题若只需知道均值最多可能到哪，就构造上界；收益问题若要保守最低水平，就构造下界。对象与方向明确后，才能判断应该减还是加误差边际。'],['全部尾部额度放在一侧','双侧95%通常两边各留2.5%，单侧95%则在一个方向留5%。所以对应临界值不同，不能把一段已算好的双侧95%区间截半后声称仍是同一单侧程序。'],['方向不能事后挑选','若事先没定，却看到结果偏高才做右侧、偏低才做左侧，实际错误率会改变。报告必须交代是预设的单侧问题还是探索选择，不让一个方向词掩盖选择过程。']],
    '单侧覆盖同样依赖模型与抽样；事后挑方向会改变实际保证，且无有限另一端不意味着参数没有现实限制。');
  put('prob-test-meaning','说机器正常，眼前数据得多奇怪才值得怀疑？','分开零假设、反常程度与可能犯的两类错误。',
    '机器标称平均装100克，抽样却平均只有97克。检验先暂按“真实平均100”构造一个参照世界，再问这样的偏离在其中有多常见。若太反常，决定拒绝该假设；若不够反常，只能说证据不足，不能证明机器一定正常。这个决定有误判风险，所以规则和显著性水平应在看数据前安排。',
    [['零假设 H₀','用来构造参照分布、接受检验的假设。','真实均值100克。'],['备择 H₁','研究希望与零假设区分的方向或其他值。','均值低于100，或不等于100。'],['α / 两类错误','α控制相应真零假设下误拒风险；漏拒是假设错了却未拒。','拒绝不等于绝对正确。']],
    'flow',[['假设平均100','建立参照世界'],['看当前偏离','97离100有多反常？'],['按预设规则决定','拒绝或证据不足']],
    '图示统计决策逻辑；任何结论均在抽样、分布与检验方向约定下解释。',
    [['先规定比较的两个主张','若只查是否少装，备择是均值小于100；若高低都异常，备择是不等于100。不同方向怎样定义“更反常”会变，不能等看到97再偷偷挑更有利方向。'],['用抽样波动衡量偏离','平均差3克是否大，要除以样本平均的标准误。若平均本来很不稳定，3克可能普通；若非常稳定，3克才显得反常，不能只凭差值绝对数下结论。'],['未拒绝不等于证明正常','检验能力不足时，实际有偏也可能没被发现。把显著性、样本量和区间一起读，比把结果硬翻成“真”或“假”更准确；任何决定都应保留适用条件。']],
    'α不是假设为假的概率，也不是所有拒绝中误判比例；未拒绝只表示当前证据不足，模型假设仍需检查。');
  put('prob-mean-test','差了3克，为什么还要除以一个尺度？','把样本平均与目标的距离换成标准误单位。',
    '两次抽样平均都比标称低3克。第一批样本平均标准误为3克，只偏了一个尺度；第二批标准误为1克，偏了三个尺度。相同克数在不同抽样噪声下，反常程度不同。均值检验把距离除以正确标准误，再按已知σ还是估计σ以及相应模型选择Z或t参照，不是见到一个平均就固定用同一张表。',
    [['检验统计量','把样本信息压成可对照参照分布的数。','(样本平均−目标)/标准误。'],['标准误','样本平均在重复抽样中的波动尺度。','S/√n常用于未知σ情形。'],['Z / t参照','尺度真正已知用Z；正态未知σ常用t。','t自由度n−1。']],
    'flow',[['平均偏离目标','97−100＝−3'],['除以标准误1','统计量−3'],['对照预设尾部','按单侧或双侧算反常']],
    '具体数仅演示标准化；检验阈值还由显著性水平、分布、自由度及方向共同决定。',
    [['距离先带着正负号','97−100＝−3，负号表示向低处偏离；不是只取绝对值后再随意选择方向。若研究少装，可看左尾；若两边异常，可看双尾，方向应事先确定。'],['分母是平均的不确定性','用单件S直接除会忽略平均更稳定这一点，正态独立样本常用S/√n。分母小，同样三克对应更多标准误，才显得与目标更不相容。'],['查表之前核对参照条件','未知总体σ且正态样本用t而非自动用Z；大样本近似需另看条件。算出一个统计量只是桥梁，不能跳过模型检查就宣布已经获得可靠p值。']],
    '精确小样本t检验依赖独立正态数据；已知或未知σ不是看数值能否算出，而是由研究信息决定。');
  put('prob-paired-test','同一个人前后差，为什么比两份名单更有用？','先构造配对差值，再把检验变成单样本问题。',
    '三位同学训练前50、70、90，后55、75、95。若当两独立组，容易混入原有水平差异；逐人相减为5、5、5，变化很一致。配对先保留真实对应，把每对压成差值，再研究平均变化；不是把任何两份等长名单按行硬配。',
    [['配对设计','两条记录有同人、同对象或明确匹配关系。','同一同学训练前后。'],['差值 D','每对按照事先指定方向相减。','后−前，改善为正。'],['配对t检验','对差值做相应单样本均值t检验。','零假设E(D)＝0。']],
    'flow',[['保留同人对应','50→55，70→75，90→95'],['逐人相减','5、5、5'],['检验差值平均','研究平均变化是否为0']],
    '三组数仅突出配对原理；差值全相同的演示数据不适合直接照用通常t计算，须注意零标准差边界。',
    [['先问两行有没有真实关系','同一人前后测量应成对；两组无关学生只是人数一样，并没有自动配对资格。配对来自设计，不是分析者为了减少噪声随意把排序相近的行凑在一起。'],['方向固定后逐对相减','采用后减前，则每人的5表示提升5分。差值本身成为一批数据，可以减少个体基线影响；若一会儿前减后一会儿后减前，会把应研究的平均变化抵消。'],['对差值检查模型','配对t方法关注差值独立且相应正态条件，而不是要求前后两列彼此独立。个体之间仍要考虑依赖；若差值尺度为0，通常t比值退化，不能机械除零。']],
    '配对需真实对应与个体间合适独立性；精确t要求差值正态，示意全相等差值需单独处理退化情况。');
  put('prob-variance-test','平均没变，忽高忽低是不是另一种故障？','把样本平方波动与目标方差比较，并按问题选择尾部。',
    '机器平均仍在100克附近，但有时装90、有时110，波动可能已经超标。方差检验不问均值是否偏移，而问总体方差是否仍是目标值。正态样本下把样本平方波动除以目标方差，能接到χ²尺。若只担心变得更不稳定，就看大值右尾；若过大过小都关心，才使用双侧规则。',
    [['方差零假设','规定参照世界的总体平方波动。','H₀:σ²＝σ₀²。'],['χ²统计量','按目标方差缩放的样本平方偏差和。','(n−1)S²/σ₀²。'],['检验方向','选择偏大、偏小或两侧的异常。','只查波动增大看右尾。']],
    'flow',[['看样本波动S²','不是只看样本均值'],['除以目标σ₀²','得到χ²统计量'],['选择异常一侧','更不稳定→右尾']],
    '独立正态样本的精确方差检验模型；方向与目标要在观察结果前安排。',
    [['均值正常不代表质量稳定','90与110可平均成100，却可能都偏离允许范围。检验方差时，应围绕样本平均计算平方偏差，不要拿均值检验的统计量代替它。'],['把波动对上目标尺度','(n−1)S²是样本平方偏差和，除以零假设的σ₀²，才得到对应自由度的χ²量。若误除以标准差而非方差，单位与参照分布都会出问题。'],['右尾不是默认万能选择','备择是波动增大时，统计量大才反常；备择为方差不等时，过大过小都可能反常。χ²不对称，两侧临界点不能像正态那样简单画成±同一个数。']],
    'χ²精确方差检验对正态条件敏感；非正态数据可能需要其他稳健方法，方向也不能看到结果后挑选。');
  put('prob-ci-test-duality','把所有没被拒绝的参数收起来，会得到什么？','在匹配条件下把置信区间看作检验反演。',
    '把均值10、11、12等候选分别当零假设，查看它们与当前数据是否太不相容。收集同一双侧检验下未拒绝者，可得对应置信区间。目标在匹配95%区间外，会被对应5%双侧检验拒绝；需要方法、方向和水平都匹配，不能混读任意输出。',
    [['检验反演','逐一检验候选参数，再收集未拒绝者。','一串候选均值拼成区间。'],['对偶','在匹配程序下，区间包含与检验拒绝相互对应。','95%双侧区间配5%双侧检验。'],['未拒绝集合','当前数据未被该检验排除的候选值。','不等于集合里每个值同样真实。']],
    'flow',[['候选逐个当H₀','10、11、12等'],['同一规则检验','保留未拒绝者'],['收成参数范围','相应置信集合']],
    '同一数据、相匹配双侧程序与水平的示意；离散、非标准方法的集合形状和对应需分别确认。',
    [['固定样本，改换参照参数','这里不是重新抽样，每次只是把另一个均值当H₀。某候选离样本平均很远，检验可能拒绝；较接近者可能未拒绝，形成一份候选兼容性清单。'],['水平与方向必须配套','若比较95%双侧区间，应使用对应5%双侧检验。换成单侧p值、不同方差假设或另一种区间方法，简单“含不含目标”对应可能不再保持。'],['兼容不等于证明正确','目标值在区间内，只表明该匹配检验未拒绝它，不证明它为真；区间外也不是逻辑上绝不可能。统计结论保留抽样风险，不能被画成绝对真假边界。']],
    '对偶依赖程序匹配；单侧、离散、近似或不同模型输出不可机械互换，未拒绝集合也不是参数后验概率分布。');
  put('prob-sample-size','想看清1克差异，收多少样本才够？','把有意义差异、误判风险和检验能力先写进设计。',
    '两机器平均差一克，单件波动十克，抽三件很难看清。样本量设计先规定要发现多小的差、容忍多少误报、希望多大机会识别真实差异，再结合波动计算。不是越多越专业；若看到p不小才反复加样本，原有错误控制可能失效。',
    [['效应量δ','研究希望识别的差异大小。','例如均值相差1克。'],['功效1−β','指定真实差异存在时，检验拒绝零假设的机会。','希望能有80%机会发现δ。'],['样本量n','计划收集的观察数量，结合尺度与风险设计。','更小差异通常需要更多n。']],
    'flow',[['先定要看清什么','差异δ＝1克'],['再定风险与能力','α与功效目标'],['结合波动设计n','不是事后追着p值加样本']],
    '图展示预先设计顺序；具体n需按检验、分组、方差估计及单侧双侧规则计算。',
    [['差异要有实际意义','如果一克差异与质量要求有关，才是合适设计目标。不能只说想显著而不说明多小差异值得识别；极大样本可把很小而无实际意义的差异也检出。'],['功效是在指定备择下算','α限制真零假设下误拒，功效则问真实差异为δ时能否发现。两者来自不同参照情形，不是把p值减一就得到功效，也不是当前假设为假的概率。'],['收集规则先安排','波动大、目标差异小或功效要求高通常需要更多样本。若按中途结果反复试到显著为止，要采用相应序贯设计或调整；不能仍宣称原固定样本程序保证不变。']],
    '样本量计算依模型和尺度输入；代表性偏差不会被堆样本修复，事后随意停止或扩样需额外控制。');
  put('prob-goodness-fit','六面骰人数不均，怎样判断偏得是否过头？','把观察频数与假设期望频数逐格比较。',
    '掷骰60次，公平假设下每面期望10次，但实际可能是8、9、11、12、9、11。不能只因不完全相等就说骰子有问题，也不能把所有差的正负相加得到零就宣布正常。拟合优度检验把各格差异平方再按期望频数校准，汇成一个量，判断这种总体偏离在假设下是否反常。',
    [['观察频数O','实际落入某类别的次数。','某面观察8次。'],['期望频数E','零假设给该格的预期次数。','60×1/6＝10。'],['χ²拟合统计量','把各格(O−E)²/E相加。','8次这格贡献4/10。']],
    'flow',[['假设公平','六格各期望10'],['逐格比较','O−E后平方并除E'],['汇成总体偏离','与相应χ²近似比']],
    '固定六类多项计数示意；χ²近似需要期望频数等条件，估过参数还要调整自由度。',
    [['期望不是本次必须做到','公平只规定各面机会1/6，60次并不强迫每格恰好10。观察与期望出现差异是正常抽样波动，检验要衡量整体差异是否大到与模型不相容。'],['平方后按格子尺度校准','一格8对10，贡献(8−10)²/10＝0.4。每格同样计算再相加，不能直接加正负差，因为总次数固定时正负本来会抵消。'],['参照与分组规则一起查','类别应互斥且覆盖全部，期望格太小时简单χ²近似可能不好。若概率参数也是从样本拟合，自由度通常要考虑估参损耗；分组不宜看到异常后随意改。']],
    'χ²是近似检验，有期望频数和估参等条件；小格可需精确或模拟方法，分组与多重尝试应透明。');
  put('prob-independence-test','是否吸烟和是否患病，联合人数能由边际解释吗？','根据独立假设构造期望格数，再比较实际表格。',
    '一百人按是否吸烟、是否患病分四格。假如两项独立，吸烟者中患病比例应与全体患病比例一致，所以某格期望人数等于行人数乘列人数再除总数。把实际格数与这些独立预期比较，能检查两项是否存在统计联系；但联系不等于吸烟在这份观察研究里已被严格证明为病因。',
    [['列联表','用交叉分类记录不同类别组合人数。','吸烟/不吸烟×患病/未患病。'],['独立期望格数','行总数乘列总数再除总人数。','行40、列20、总100→期望8。'],['独立性检验','比较实际格数与独立模型期望的总体偏离。','常用χ²统计量。']],
    'flow',[['边际人数','吸烟40，患病20，总100'],['独立模型预测','40×20/100＝8'],['与实际该格比较','再汇总全部格偏离']],
    '随机抽样交叉分类模型；8是独立假设下的期望，不是由观察表直接宣布成立。',
    [['把独立翻译成比例相同','全体患病率为20/100，若与吸烟独立，40位吸烟者也按同一比例预期患病，所以该格为8。先从概率相乘推人数，比只背行乘列更容易理解。'],['四格一起看偏离','实际若不是8，并不单凭这一格就定结论；各格按(O−E)²/E汇总，且行列边际约束影响自由度。χ²检验还需期望格数等近似条件。'],['关联不自动给因果箭头','观察到统计联系可能涉及年龄、抽样等共同因素。独立性检验回答的是当前模型下两分类能否独立解释，不直接区分原因、后果或未控制因素。']],
    '独立性χ²近似需合适抽样与格数；配对分类不能冒充独立个体表，统计关联也不能单独证明因果。');
  put('prob-p-value','p＝0.03，是“假设只有3%可能对”吗？','把p值读成在零假设参照下的尾部反常概率。',
    '先假定硬币公平，预设用正反偏离程度判断反常。观察结果后，p值问的是：在公平模型里，出现眼前这么偏或更偏结果的机会有多大。若为0.03，说的是这个参照世界的尾部比例，不是“硬币公平的概率3%”，也不是“研究结论只有3%可能错”。条件方向反过来，就把问题换掉了。',
    [['p值','在指定零假设与规则下，统计量至少同样反常的概率。','不只是恰好眼前一份数据的概率。'],['零假设参照','计算p值时暂定成立的模型世界。','本例先按公平硬币算。'],['显著性水平α','事先设定的检验决策门槛。','p≤0.05可按预设规则拒绝。']],
    'flow',[['先假设模型成立','按公平硬币计算'],['定义更反常区域','眼前偏离及更极端结果'],['累计尾部机会','这份机会叫p值']],
    '图示p值的条件方向；单侧双侧、统计量与抽样停止规则都会影响“更反常”的定义。',
    [['条件在假设这一边','计算从“若H₀成立”出发，再衡量数据尾部。它没有使用参数先验，也没有反过来算H₀为真的概率；把箭头倒过来并非同一个条件概率。'],['眼前以外更极端也算进去','p不是只算本次具体排列有多稀少，许多具体排列都很稀少。必须按预设统计量和方向，累计所有至少同样反常的结果，才能形成检验用的尾部度量。'],['门槛不能替代效应大小','p小可能来自大样本下很小差异，p大也可能只是资料不足。报告还应说明差异估计、区间、设计及分析过程，而不是把0.05当事实真假的分界线。']],
    'p值不是假设概率、效应大小或结论错误率；多重尝试与数据驱动选择会影响解释，应连同分析规则报告。');
  window.PLAIN_BEGINNER = Object.assign(window.PLAIN_BEGINNER || {}, data);
})();
(() => {
  const data = {};
  const put = (id, plainTitle, goal, story, terms, kind, nodes, caption, steps, boundary) => { data[id] = {plainTitle,goal,story,terms:terms.map(([word,meaning,example])=>({word,meaning,example})),diagram:{kind,nodes:nodes.map(([name,detail])=>({name,detail})),caption},steps:steps.map(([title,text])=>({title,text})),boundary}; };
  put('prob-joint-table','两个人的分数，为什么要放进同一张表？','读懂两项数值同时出现的机会，而不是各自单独的排名。',
    '观察一天上午和下午是否下雨，用X记上午、Y记下午，雨为1，无雨为0。只知道上午下雨一半、下午下雨一半，还不知道它们是否常一起下。把四种配对机会放进二维表，才能分清“各看一半”背后的共同关系。表中每格是一种上午与下午的完整组合，不是两个概率随意相乘。',
    [['联合分布','同时记录两个变量配对取值的概率。','P(X＝1,Y＝1)表示两段都下雨。'],['边际概率','暂时不管另一项，把相关格子的机会合并。','上午下雨可含下午雨或不雨。'],['归一化','整张表所有完整配对的概率之和为1。','四格共同分完一天的可能情况。']],
    'memory',[['上午不雨X＝0','配下午0或1'],['上午下雨X＝1','配下午0或1'],['四格共一整天','全部格子的概率和为1']],
    'X、Y均用0/1记录天气；四个配对互斥，表格保留两项的共同信息。',
    [['一格必须同时读两个坐标','读到(1,0)这一格，要说“上午下雨、下午不雨”，不是只读成上午下雨。每一天恰落一格，所以格子中的概率可以汇总成相应事件。'],['整行合并会丢掉一项细节','把X＝1的一行加起来，得到上午下雨概率，不再区分下午怎样。同样的上午边际可能由不同的行内分配构成，不能反过来凭边际还原整张表。'],['相乘是待检验关系','只有相应独立条件成立，联合格才等于两项单独概率相乘。建表的第一步是给出或计算配对机会，不是因为有两项就无条件用乘法。']],
    '0/1天气是简化编码；两项边际相同并不能确定依赖关系，独立必须用联合模型检验。');
  put('prob-joint-density','两项测量的机会，为什么变成一片面积？','先画允许的平面区域，再在区域内累计联合密度。',
    '在单位正方形里随机落一点，横坐标X、纵坐标Y。现在只允许点落在X与Y相加不超过1的三角形里；正方形另一半根本不是候选。机会要先放在这块土地上，再按小块面积累计。联合密度是在二维区域中的机会浓度，某一个坐标点本身没有一份正概率，整块区域才有面积。',
    [['联合密度 f(x,y)','平面中每单位面积分配机会的浓度。','三角形上恒为2，总面积1/2。'],['支持域','模型允许分配正密度的区域。','x≥0、y≥0、x＋y≤1。'],['二重积分','把平面区域里的小面积贡献累计起来。','恒定密度时等于密度乘面积。']],
    'branches',[['底边范围','0≤x≤1'],['每处高度限制','0≤y≤1−x'],['整块三角形','面积1/2，密度2']],
    '三角形内均匀模型，整个概率为2×1/2＝1；坐标限制共同决定土地形状。',
    [['先画不可能的位置','本模型里x、y不能为负，且两者之和不能超过1。比如(0.8,0.8)不在土地上，其密度为0；不能因为两个坐标分别都在0到1之间就把它保留。'],['固定一列看上边界','给定横位置x＝0.4，纵坐标最多到0.6。横位置改变，允许高度也随之变化，所以积分上限要跟着x走，而不是始终把y从0积到1。'],['机会是土地上的总量','整个三角形面积1/2，乘密度2得到1。求其中某子区域的机会，先与允许土地取交，再计算面积贡献；图形限制不能被公式自动忽略。']],
    '恒定密度乘面积只适用于本例；一般密度随位置变化，要积分，且必须先与支持域取交。');
  put('prob-bivariate-normal','两项测量一起波动，云团为什么会斜着？','分开理解中心、宽度和共同偏动，避免把相关直接说成因果。',
    '每位同学测身高与臂展，得到平面上的一个点。许多点可能聚成一团斜长的云：较高者也常臂展较长，但不是每人都压在一条直线上。二元正态模型用两个中心、各自宽度和共同倾向描述这种概率云。它是对整体形状的假设，不是看见散点大致成椭圆就自动获得的证明。',
    [['二元正态','两个变量共同服从的一类椭圆形概率模型。','非退化模型有二维密度云。'],['均值向量','两项各自平均位置合成的中心坐标。','中心为平均身高与平均臂展。'],['相关系数ρ','去掉单位后的线性共同变动程度。','ρ为正时云团常向右上倾斜。']],
    'compare',[['中心在哪里','两个均值决定云心'],['各方向多宽','各自标准差决定尺度'],['怎样一起偏','ρ描述线性倾向']],
    '三项是模型不同特征；非退化二元正态要求相应协方差矩阵合法，不能任意填参数。',
    [['先移到共同中心','每个点有两个坐标，因此中心也要给两项均值。分别减去各自均值，才是在讨论两项偏离自己中心的方向，而不是拿厘米数值直接比较谁更大。'],['宽度与斜向不同','身高标准差大说明横向散得宽，臂展标准差大说明纵向宽。相关系数再描述两者是否常同向偏，不能只凭一项方差推断云团朝哪边倾斜。'],['特殊独立结论有前提','在联合正态模型中，不相关可推出独立；仅两项分别是正态却不够。相关更不自动证明某一项造成另一项，模型关系和因果解释仍要分开。']],
    '椭圆是非退化联合正态的直觉图；分别正态不保证联合正态，相关也不自动具有因果含义。');
  put('prob-marginals','只看上午天气，下午的格子怎么办？','通过合并一行或积分一个坐标，得到边缘分布。',
    '一张表同时记上午和下午的天气。若你现在只想知道上午下雨的机会，就把“上午雨、下午晴”和“上午雨、下午雨”两格相加；下午的区别被收起来，上午的信息被保留。边缘分布就是这种暂时不看另一坐标的汇总。连续情形改为沿另一方向累计密度，思路仍是合并所有可能来路。',
    [['边缘分布','从联合模型中只保留某一个变量的机会分配。','把X＝1对应所有Y格相加。'],['求和 / 积分','离散把格子相加，连续沿允许范围累计。','f_X(x)＝∫f(x,y)dy。'],['支持范围','给定保留坐标后，另一坐标实际允许变化的范围。','三角形中y最多为1−x。']],
    'branches',[['上午雨下午晴','机会0.2'],['上午雨下午雨','机会0.3'],['上午雨合计','0.2＋0.3＝0.5']],
    '两格同属X＝1且互斥；忽略Y是汇总，并不是假设Y不存在或与X独立。',
    [['确定要保留哪项','要的是X的分布，就固定X取值，遍历所有允许的Y。不要把沿哪边求和全靠表格边缘位置记忆；即便转置表，保留X、合并Y的规则也不会变。'],['合并所有互斥来路','上午雨可以伴下午晴或雨，两种完整结果不能在同一天同时成立，因此机会直接相加。0.2与0.3合成0.5，回答上午雨而不限定下午的问题。'],['连续时边界随图形走','若联合土地是x＋y≤1的第一象限三角形，固定x后应让y从0走到1−x。边缘密度要积完整允许切片，不是看见两个变量就统一积0到1。']],
    '由联合可汇总边缘，反过来一般不能由两个边缘唯一恢复联合；连续积分范围由支持域决定。');
  put('prob-conditional-discrete','选定一行之后，为什么要把它放大成总和1？','用行内份额理解离散条件分布。',
    '四格联合表中，上午雨且下午晴的概率为0.2，两段都雨为0.3。已知上午下雨后，只剩这两格，它们原本合计0.5。条件分布把这份剩余机会重新当作全部，于是下午晴为0.2除0.5，下午雨为0.3除0.5。筛选和重新归一是两步，不能只划掉别的格子却不重新分配。',
    [['条件分布','给定一个变量的信息后，另一个变量的概率配表。','已知上午雨后看下午天气。'],['归一化分母','被条件保留下来的总概率。','0.2＋0.3＝0.5。'],['条件概率','目标格概率除以条件范围的总概率。','下午晴为0.2/0.5＝0.4。']],
    'flow',[['选上午雨一行','保留0.2与0.3'],['求这一行总量','0.5'],['整行除以0.5','变成0.4与0.6']],
    '条件概率为正时，保留行内各格相对比例，再把总量从0.5调整到1。',
    [['条件就是先缩清单','上午不雨的那些格不再是候选，但保留的两格仍带原来的联合机会0.2和0.3。这一步得到的是原总体中的半份机会，不是完整的条件分布。'],['用条件的总量作新单位','被保留的合计为0.5，把它当作新世界的一整份，所以每格除以0.5。下午晴变0.4、雨变0.6，且两者相加为1，这是必要检查。'],['别把行与列条件倒过来','已知上午雨，是固定X后看Y；已知下午雨，则固定Y后看X，候选范围与分母都变了。相同联合格可以出现在两个问题里，但不能因此条件概率相同。']],
    '本例条件有正概率；条件概率为零时不能直接相除，连续条件分布也需另外建立密度式解释。');
  put('prob-conditional-density','连续变量固定一处，切片怎样变成概率？','理解联合密度切片还需要按该处边缘密度归一。',
    '想象一块三角形土地上均匀撒机会，横坐标为X、纵坐标为Y。固定X＝0.4时，可用的竖向切片只到Y＝0.6。切片形状告诉你Y在哪些地方可能，但原来的高度还没有把这一小世界的总量调成1。连续条件密度要用联合密度除以相应边缘密度，而不是把零宽竖线的概率拿来作分母。',
    [['条件密度 f(y|x)','固定X的信息后，Y在单位长度上的机会浓度。','x＝0.4时Y均匀在0至0.6。'],['边缘密度 f_X(x)','把该横位置所有允许Y的联合密度累计得到。','三角形密度2时为2(1−x)。'],['归一化','把条件下允许范围的密度面积调成1。','高度1/0.6乘宽0.6等于1。']],
    'flow',[['固定横位置','x＝0.4'],['找允许纵范围','0≤y≤0.6'],['调整切片高度','条件密度1/0.6']],
    '第一象限x＋y≤1、联合密度2的模型；在边缘密度为正的位置使用密度比。',
    [['先画切片的长度','X固定为0.4时，x＋y≤1要求y≤0.6，且y不小于0。允许范围只有0.6长，不是整个0到1。条件密度必须在此范围之外为0。'],['原切片高度不能直接使用','联合高度2沿0.6长度累计为1.2，这是横位置处的边缘密度，不是某条零宽线的概率。用2除以1.2得到1/0.6，才把Y这一维条件面积调成1。'],['用条件面积检查答案','若问条件下Y≤0.3，允许长度的一半为0.3，乘高度1/0.6得到1/2。检查的是在既定X切片内的相对份额，不再对所有横位置一起计算。']],
    '普通密度模型里P(X＝0.4)为0，不能直接当事件概率相除；条件密度式在边缘密度正处按相应意义定义。');
  put('prob-variable-independence','知道第一项数值，第二项的机会表会改吗？','从联合分布与条件分布检查变量独立。',
    '掷两枚独立公平硬币，用X、Y分别记各自是否正面，四种组合各占四分之一。知道X是1，Y仍各有一半；知道X是0也一样。变量独立要求这种不改变机会的关系覆盖所有相关取值与事件，不是只碰巧找到一格满足乘法，或只看到两条平均数没有同步变化。',
    [['随机变量独立','有关两变量的全部相应联合机会可按各自边缘拆开。','离散时每格都应等于两边际乘积。'],['联合 / 边际','配对机会 / 暂不看另一项的单独机会。','共同为1占1/4，各自为1占1/2。'],['条件不变','在条件概率适用处，知道一项不改变另一项分布。','固定X任一值，Y仍一半一半。']],
    'compare',[['X＝0这一行','Y为0/1各占1/2'],['X＝1这一行','Y为0/1各占1/2'],['原Y分布','同样各占1/2']],
    '四个联合格均为1/4的模型；两条条件配表与原配表一致，而非只检查一个概率。',
    [['先算两份边际账','联合表四格各1/4，固定X的一行总和1/2，固定Y的一列也总和1/2。每格1/4都等于所在行边际1/2乘所在列边际1/2。'],['逐条件比较整份分布','已知X＝1时，Y为1的概率是(1/4)/(1/2)＝1/2；已知X＝0同样。这里两种取值都查过，不能只在某一个条件下碰巧不变就声称一般独立。'],['平均关系不够强','协方差为0只检查一种线性共同偏动，不能覆盖所有事件。变量独立讨论的是完整分布关系，之后求和、乘积等时能否拆概率，也应从这项完整假设出发。']],
    '独立是联合模型的性质，不是从样本散点看不出直线就能确认；连续与离散判据的形式也要分别使用。');
  put('prob-sum-convolution','两笔收入加成3，有哪几条来路？','枚举所有相加到目标值的组合，再计算和的分布。',
    '甲收入可能1或2元，乙可能1或2元。合计3元既能来自甲1乙2，也能来自甲2乙1。要求和的概率，不能只选其中一种；要把全部来路的联合机会合起来。连续数值时，来路沿平面中的x＋y＝z排列，卷积就是在相应条件下把这些贡献累计的一种写法。',
    [['和变量 Z＝X＋Y','把两个数相加后得到的新随机变量。','1＋2与2＋1都标成3。'],['卷积','独立变量求和时，沿互补取值累计概率或密度的规则。','固定总和3，遍历x与3−x。'],['联合机会','两个指定数值一起出现的概率。','独立时可用各自概率相乘。']],
    'branches',[['来路一','X＝1，Y＝2'],['来路二','X＝2，Y＝1'],['合到同一标签','Z＝3，累加两路机会']],
    'X、Y各等可能取1或2且相互独立时，两路各占1/4，Z＝3共占1/2。',
    [['先定总和，再找所有配对','目标为3，X可为1时Y必须为2；X为2时Y必须为1。检查取值范围后只有这两路，不能把X与Y各自最可能值相加就当完整分布。'],['联合格先算清再相加','本例每个变量的两值各占一半且独立，所以两路共同机会分别为1/4，合计1/2。若不独立，依然要合来路，但每路必须使用真实联合概率。'],['连续情形看斜向来源','总和z固定后，y随x取z−x，允许范围还受原支持域限制。独立时可把联合密度写成两份边缘密度乘积，再积分，这才得到常用卷积式。']],
    '枚举来路始终要做；把每路概率写成边际乘积需独立，连续积分还必须检查支持域与边界。');
  put('prob-extremes','最大值不超过5，意味着每个人都怎样？','把最大最小事件翻成全部或至少一个，再选正向或补事件。',
    '三个人各测一次等待时间。最大值不超过五分钟，等价于三个人全都不超过五分钟；最小值超过五分钟，等价于三个人全都超过五分钟。原本难抓的最大最小，翻译成“全部”后反而容易。至于最小值不超过五分钟，是至少一人做到，可以先算全部没做到，再用一减去它。',
    [['最大值 M','多项数值中最大的一个。','M≤5要求每项都≤5。'],['最小值 m','多项数值中最小的一个。','m>5要求每项都>5。'],['补事件','把“至少一个”改成“并非全部没有”。','P(m≤5)＝1−P(全>5)。']],
    'compare',[['最大≤5','三个人全部≤5'],['最小>5','三个人全部>5'],['最小≤5','至少一人≤5']],
    '三项等待事件的等价翻译不需要独立；把“全部”的概率连乘时才需要相应独立假设。',
    [['先做逻辑翻译','如果三人里有一人超过5，最大值就超过5；所以最大不超过5只能是三人都不超过。这一步来自最大值定义，不是某个特殊分布公式。'],['再看机会能不能相乘','若三人独立且每人不超过5的概率为0.8，则最大不超过5的概率为0.8³。若同受一次堵车影响而有关联，逻辑等价仍成立，乘法却未必成立。'],['至少一个优先试反面','最小不超过5就是至少一人不超过5。反面是三人全超过5；本例独立同概率下为0.2³，因此所求为1−0.2³，而不是简单3×0.8。']],
    '事件翻译可一般使用，但幂形式要求独立同分布；阈值处有点质量时，严格大于和不大于不能随便互换。');
  put('prob-product-ratio','乘积小于1，原来的点会落在哪片区域？','先把新变量条件画回二维平面，再求区域概率。',
    'X和Y都是正数，想知道乘积XY不超过1。先固定X：若X＝2，Y最多0.5；若X＝0.5，Y可到2。边界不是一条直线，而是Y＝1/X的一支曲线。商Y/X的条件则需先注意分母能否为零、正负是否改变方向。先找原平面上的区域，比跳过几何直接背密度变换更稳。',
    [['乘积 / 商变量','把两个旧数相乘或相除得到的新变量。','Z＝XY，W＝Y/X。'],['原区域','满足新变量目标条件的所有旧坐标点。','正数下XY≤1即Y≤1/X。'],['雅可比','连续换坐标时校正小面积伸缩的因子。','不能只替换字母而忽略面积变化。']],
    'branches',[['X＝0.5','Y≤2'],['X＝1','Y≤1'],['X＝2','Y≤0.5']],
    '仅画X、Y为正时XY≤1的边界切片；真正积分区域还要与原模型支持域取交。',
    [['先把符号条件讲明','本图限定X与Y为正，才可以把XY≤1直接除以X写成Y≤1/X。若X可能为负，除法会翻转不等号；若X＝0，商还可能根本没有定义。'],['按切片找完整土地','在X＝2处可保留Y不超过0.5，在X＝0.5处可保留Y不超过2。把所有允许切片拼成区域，再与原模型土地相交，不能只算曲线上的一条零面积边界。'],['概率仍由旧联合模型给','找到区域后，用联合密度累计区域内部机会；若进一步求新密度，才处理坐标变化与面积伸缩。独立与否影响联合密度，不能因出现乘积就假定变量独立。']],
    '图示限定正变量；含负值、零分母、非一一对应变换时须分区域处理，密度换元还需正确面积因子。');
  put('prob-expectation-discrete','平均能是0.8，为什么实际却只能拿0或2？','把期望理解成按机会加权的长期平衡点。',
    '游戏有六成机会拿0元，四成机会拿2元。一次只能拿0或2，但把机会当份额加权，平均为0×0.6＋2×0.4＝0.8元。这个0.8描述模型的平均账，不承诺下一次会发八角，也不等于最容易出现的0。把概率当砝码摆在数轴上，期望就是这份机会重量的平衡位置。',
    [['数学期望 E(X)','将取值按各自概率加权后汇总的平均。','0×0.6＋2×0.4＝0.8。'],['权重','一个数值在平均账中占的份额。','2元占0.4份，不是占一半。'],['众数','单独出现机会最大的取值，与平均不同。','0比2更常见，但期望是0.8。']],
    'memory',[['0元位置','放0.6份重量'],['2元位置','放0.4份重量'],['平衡位置','E(X)＝0.8元']],
    '模型只有0与2两种收益；平衡点可不在任何实际取值上，也不是保证每次获得的收益。',
    [['先把每个结果贡献分开','0元乘0.6为0，2元乘0.4为0.8，两项相加才是加权平均。不能直接把0与2除以2得到1，因为两个收益并非各有一半机会。'],['平均不需要是可取值','0.8落在0与2之间，却不是这场单次游戏的奖项。期望是整体机会分配的数字特征，和“下一次会得到什么”不同，也和“哪个结果最常见”不同。'],['应用时把成本也算进账','若每局收费1元，净收益变量应减去1，期望净收益为−0.2。平均为负不排除偶尔赢，也不能只看头奖2元就判断游戏划算。']],
    '有限例子期望存在；无限取值需检查收敛。把期望与长期平均联系，还要具备相应重复实验条件。');
  put('prob-expectation-continuous','连续曲线的平均，为什么不只是最高处？','用密度加权，并知道平均值未必存在。',
    '等待时间在0到2分钟内均匀分布。每一小段的机会来自密度乘长度，把每段时间值乘这份机会再累加，平均在1分钟。曲线最高处不负责决定期望；如果远处很少发生的极大值贡献过重，甚至可能没有有限平均。连续期望需要先问加权总账能否收得住，而不是见到一个积分就默认有答案。',
    [['连续期望','把取值乘密度，再在整个允许范围累加。','E(X)＝∫x f(x)dx。'],['绝对可积','取值绝对值的加权总量有限，用来保证有限期望。','不能靠正负无穷抵消造一个平均。'],['尾部','很远处大数值仍可能出现的概率部分。','极少大损失也可能影响平均。']],
    'flow',[['位置x','该处等待时间'],['小段机会','f(x)乘小段长度'],['加权累加','把x乘该段机会后求和']],
    '0至2均匀模型的密度为1/2，平均为1；积分是小段加权累积，而非曲线高度的平均。',
    [['分清位置与浓度','在x附近的一小段，概率约是密度f(x)乘小段长度；这一小段对平均的贡献，还要再乘代表时间x。只积分密度会得到总概率1，不是平均等待。'],['在全范围累计贡献','均匀0到2的例子，左右对称于1，所以平均为1；积分x×1/2也给同一结果。对称和有界在这里让判断简单，不能据此认为所有连续分布都有中心平均。'],['先查尾部再做抵消','当正负两侧贡献都无限大，不能写成无穷减无穷再宣布平均为0。某些分布看似围着0对称却没有期望；“对称中心”与“存在的期望”是两件事。']],
    '图示是有界均匀例子；无限范围必须检查可积性，形式对称或主值积分不能冒充通常定义的有限期望。');
  put('prob-lotus-linearity','要算平方的平均，必须先求平方后的分布吗？','利用原分布算函数期望，理解线性不要求独立。',
    'X取1或3，各占一半。平方的平均可直接把1²与3²按原机会加权，不必重做新分布。另有方便规则：两项收入相加的平均，等于各自平均相加，即使有关联也成立。但平方的平均一般不等于平均再平方，不能让任何函数都穿过期望符号。',
    [['函数期望','对原取值先应用函数，再按原概率加权。','E(X²)＝(1＋9)/2＝5。'],['线性性','平均允许加减与乘固定常数穿过期望符号。','E(X＋Y)＝E(X)＋E(Y)。'],['非线性','平方等操作不受上述线性规则保证。','E(X²)不等于[E(X)]²。']],
    'compare',[['先平方再平均','1与9平均为5'],['先平均再平方','2的平方为4'],['相加的平均','可分别平均后相加']],
    'X等可能为1或3，平方给出5与4的差别；相加的期望规则不需X与Y独立。',
    [['函数先作用在每个旧值','X＝1时平方为1，X＝3时平方为9，仍各有一半机会。直接做1×1/2＋9×1/2就得到5，原始概率没有因换成平方而随意改变。'],['线性来自逐项加权分配','有限期望下，加法的加权总账可以拆成两份，所以无须先证明独立。两个相关项目的总收入平均仍能相加，独立主要在某些乘积或分布拆分时才起作用。'],['平方不能按同样方式穿过','本例E(X)＝2，平方得4，与E(X²)＝5不同。写公式时先认清是加法、常数倍还是非线性函数，不能把一个好用的符号规则推广到任何括号。']],
    '使用线性等式需相应期望存在；乘积期望拆成两份通常需要额外条件，平方不属于线性变换。');
  put('prob-variance','平均一样，为什么一个方案更忽高忽低？','用离中心的平方距离衡量波动。',
    '甲每天固定拿2元，乙每天等机会拿0或4元，两者平均都是2。平均账看不出乙更不稳定，所以再量每次偏离平均多少。偏离有正有负，直接平均会抵消；平方后都变成非负，再按机会平均，得到方差。乙的方差为4，甲为0，差别就在这份围绕中心的波动账里。',
    [['方差 Var(X)','偏离期望的距离先平方，再求平均。','乙为[(0−2)²＋(4−2)²]/2＝4。'],['标准差σ','方差的非负平方根，单位回到原量。','方差4元²对应标准差2元。'],['中心化','先减去该变量的平均位置。','0变−2，4变＋2。']],
    'flow',[['先减中心2','偏差为−2、＋2'],['每个偏差平方','都变成4'],['再按机会平均','方差4，标准差2']],
    '乙等可能取0或4，三个步骤解释平方平均；不是先把偏差平均成0再平方。',
    [['先确定各自中心','两方案平均都为2，但甲每次偏差为0，乙则在−2与＋2之间。先减中心才能比较围绕各自通常位置的散开程度，直接比较原始数值会混入中心差别。'],['平方避免正负相互抵消','乙偏差平均为0，不能说它完全不波动。先平方得到两个4，再平均为4，才保留距离信息；顺序若改成先平均再平方，就把想测的波动抹掉了。'],['分清方差单位与标准差','若X单位为元，方差单位是元的平方，不宜直接说“波动4元”。开平方得标准差2元，适合与原测量尺度对照；方差大也不等于每次都离中心那么远。']],
    '本例有限取值方差存在；一般变量需检查二阶矩。方差描述整体平方波动，不能单独决定分布形状。');
  put('prob-covariance','两个人是常一起高于自己平均，还是一高一低？','把各自偏差相乘，理解协方差正负。',
    '每天同时记气温与冷饮销量。若天热于本季平均时销量也常高于自己平均，两项偏差乘起来多为正；天冷而销量也低，两负相乘仍为正。协方差把这种共同偏动的乘积平均起来。它先减各自中心，不是在比较两个原数谁大；数值还带双方单位，换单位时大小也会变。',
    [['协方差 Cov(X,Y)','两变量各自减平均后，偏差乘积的平均。','E[(X−EX)(Y−EY)]。'],['同向 / 反向偏动','常在各自中心同侧 / 异侧。','同高或同低给正乘积。'],['协方差为0','这种线性共同偏动平均抵消，不等于所有联系都没有。','平方关系可能仍紧密相连。']],
    'compare',[['两项都高','＋偏差×＋偏差为正'],['两项都低','−偏差×−偏差为正'],['一高一低','偏差乘积为负']],
    '图只解释偏差乘积符号；总体协方差还要按各情况机会或数据规则汇总。',
    [['各自减自己的平均','气温要减平均气温，销量要减平均销量，不能用同一个数字作两者中心。之后比较的是相对各自通常水平高低，而不是温度数值与销量数值谁更大。'],['给共同偏动记正负账','同高和同低都给正乘积，一高一低给负乘积；按机会平均后，哪种贡献更强决定协方差符号。单独某一天同向，不能立刻宣布总体协方差一定为正。'],['单位与因果分开看','温度改用另一单位会改变协方差数值尺度，它不天然落在−1到1。正协方差只是共同线性变化的描述，也不能单凭它证明热天气导致销量变化。']],
    '协方差需相应矩存在；零协方差不普遍推出独立，正负相关描述也不自动具备因果含义。');
  put('prob-correlation','同样一起涨，换单位后怎样仍能比较？','用各自标准差消去协方差单位，认识线性相关的限制。',
    '把气温从摄氏换成华氏，会把共同变化的数字放大，但人们不希望“关联程度”只因单位换了就变强。于是把协方差再除以两项各自标准差的乘积，得到没有单位的相关系数。它介于负一和一，专门反映直线式共同偏动；散点弯成一个圈或抛物线，仍可能相关为零。',
    [['相关系数ρ','协方差除以两项正标准差乘积的无量纲指标。','ρ＝Cov(X,Y)/(σ_Xσ_Y)。'],['线性关系','一项变化时另一项可按直线规律变化。','Y＝2X＋1为正向直线。'],['无量纲','结果不带厘米、元等单位。','正常换用正比例单位不改变ρ。']],
    'flow',[['共同偏动','协方差带双方单位'],['除以各自尺度','用σ_X乘σ_Y'],['得到ρ','−1至1的线性指标']],
    '标准差都为正、二阶矩存在时定义ρ；正负一是精确线性关系的特殊边界，不是一般散点必达到。',
    [['先让两项都按自身尺度看','协方差同时受两项波动大小影响。除以标准差乘积，相当于先把每项偏差换成各自标准差单位，再看共同变化，所以相关系数不再随厘米改米等正比例换单位而改变。'],['正负说明方向，绝对值看直线程度','ρ靠近1表示正向线性共同波动强，靠近−1表示反向强。负号不是“关系弱”，而是方向；比较强弱通常看绝对值，同时仍要注意样本不确定性。'],['只对线性提问作答','ρ＝0不意味着两项毫无关系。例如一项取值的平方可由另一项完全决定，左右对称时线性偏动却抵消。先看散点形状，再读这一个数字，别让它替你回答所有问题。']],
    '常量变量标准差为0时通常不能定义相关系数；相关衡量线性关系，不能单独证明独立或因果。');
  put('prob-uncorrelated-normal','X一知道就能算Y，为什么相关还能是0？','用平方反例分开不相关与独立，并记住联合正态特例。',
    'X等机会取−1、0、1，令Y＝X²。只要知道X，Y立刻确定，当然不能说两者没有联系。但X左右对称，负侧与正侧对线性共同偏动的贡献抵消，所以协方差为0。这个小表直接打破“不相关就是独立”的误解；联合正态条件下才有额外的特殊结论，不能把特殊通行证发给所有变量。',
    [['不相关','协方差为0，只排除了该线性偏动指标。','X与X²在本对称例中不相关。'],['独立','知道一项不会改变另一项完整分布的关系。','本例知道X＝0就确定Y＝0，不独立。'],['联合正态特例','在联合正态模型下，零协方差可推出独立。','仅分别正态不够。']],
    'memory',[['X＝−1','Y＝1'],['X＝0','Y＝0'],['X＝＋1','Y＝1']],
    '三种X各占1/3，Y被X完全决定；左右对称使E(XY)为0，不能因此抹掉依赖。',
    [['先看能不能从一项预测另一项','X＝0时Y必为0，X为±1时Y必为1，条件信息明显改变Y的机会。这已经能判定不独立，不必先把相关公式算完再猜。'],['再算为什么线性账抵消','E(X)＝0，E(XY)由−1、0、1各三分之一相加为0，所以协方差为0。左右两侧方向相反的贡献抵消，平方形状的联系仍完整存在。'],['使用特例先核对联合模型','若有充分依据说明两变量联合正态，则零协方差能推出独立。分别画出两个钟形边缘并没有确认联合正态，不能跳过这个前提直接借用结论。']],
    '本例是离散平方反例，不是正态模型；联合正态特例依赖共同分布，不能只看每个变量单独正态。');
  put('prob-moments-matrix','很多项一起波动，怎样整理成一张不乱的表？','把均值、平方量与协方差矩阵连成统一的波动记录。',
    '同时记录身高和体重，每项自己有多分散，两项又是否一起偏，都需要保留。把两项方差放在表的对角，把共同偏动放在两个对称格，就得到协方差矩阵。它不是随便填满的数字方阵：任何线性组合的方差都不能为负，所以整张表必须满足共同约束。先读每格职责，再看矩阵符号。',
    [['矩','对变量的幂或乘积求平均得到的特征。','一阶矩是均值，二阶涉及平方。'],['协方差矩阵Σ','对角放各自方差，非对角放两项协方差。','Σ₁₂与Σ₂₁相同。'],['半正定','任意线性组合的方差都不小于0的矩阵性质。','不能填出一种组合方差为负。']],
    'memory',[['左上与右下','分别是Var(X)、Var(Y)'],['另两个对称格','都是Cov(X,Y)'],['任意加权合成','方差必须≥0']],
    '二变量协方差表的读法；图中没有声称协方差矩阵能独自决定任意分布。',
    [['先把每个格子翻译出来','对角格描述单项偏差平方的平均，非对角格描述两项偏差乘积的平均。两个非对角相等，是因为相同乘积交换次序不变，不是额外强加的独立假设。'],['系数向量是在配权重','若把X、Y按系数a、b相加，新方差会包含a²Var(X)、b²Var(Y)和2abCov(X,Y)。矩阵写法把同一笔计算压缩，符号没有省掉这些具体贡献。'],['合法性要整张表一起查','单个对角非负还不够；若共同偏动填得过大，某个加权方向可能给出负方差，这不可能是真模型。半正定就是把所有方向的非负要求合成一项约束。']],
    '本课二阶特征需存在；协方差矩阵一般不能唯一确定分布，只有特定模型族中才有更强描述能力。');
  put('prob-lln','前面连输，后面就一定会补回来吗？','区分样本平均稳定与独立结果不存在补偿记忆。',
    '独立掷公平硬币，前十次可能只有三次正面。继续掷很多次，前三次偏低的影响被更大的总次数摊薄，比例有趋向一半的规律；不需要下一次特意偏向正面来还债。大数定律说的是合适条件下平均或频率的稳定，不保证每一段都精确，也不让短期亏损变成未来必赚的信号。',
    [['样本平均','把这批观察值相加，再除以观察次数。','0/1正面记录平均就是正面频率。'],['大数定律','在相应条件下，样本平均随次数增大趋近总体均值。','独立同分布且均值存在的一类结论。'],['依概率趋近','偏离固定误差范围的机会随样本量变小。','不等于每次新增后都更靠近。']],
    'timeline',[['少量记录','比例可明显波动'],['增加合适重复','旧偏差被更大次数摊薄'],['长期平均稳定','不是下一次补偿过去']],
    '箭头表示增加样本量的模型趋势，不表示任一具体轨迹都单调靠近目标。',
    [['用0和1把频率写成平均','正面记1、反面记0，总和就是正面次数，除以次数就是频率。公平独立模型每次均值为0.5，大数定律把这种样本平均与均值联系起来。'],['稳定不等于步步改进','样本从100次增加到101次，比例可能暂时离0.5更远；结论讨论样本量变大时偏离机会的趋势。不能把概率意义上的靠近改写成每一次记录都更准。'],['未来不记着前面欠了多少','独立模型下，下一次正面仍是0.5。前段偏差占总量比例变小，就可能帮助整体接近，而不需要后段专门出现反向偏差把旧账严格抵消。']],
    '大数定律有条件与不同版本；强依赖、分布变化或均值不存在时，不能不加检查套用独立同分布结论。');
  put('prob-chebyshev','不知道曲线长什么样，只知方差能保证多少？','从平方偏差平均给出保守尾概率上界。',
    '某误差平均为0，方差为4。即使不知道误差曲线长什么样，也能限制“离0至少6”的机会：达到那一区域，每次平方偏差至少36，而全部平方偏差平均只有4，所以那一区域占比不可能任意大。切比雪夫不等式给出4除36的上界，它是安全上限，不是准确预测有九分之一会超标。',
    [['切比雪夫界','用方差约束偏离均值至少a的概率上界。','P(|X−μ|≥a)≤σ²/a²。'],['上界','真实概率不能超过的保守限制。','≤1/9不等于恰好1/9。'],['绝对偏差','离均值距离，不分在左侧还是右侧。','|X|≥6包括≤−6与≥6。']],
    'flow',[['进入远处尾部','偏差距离至少6'],['平方代价至少36','每份尾部机会贡献≥36'],['总平方账仅4','尾部概率≤4/36']],
    '有限方差σ²＝4、阈值a＝6的模型；界适用于两侧总尾部，不要求正态。',
    [['先把尾部变成平方成本','若|X|至少6，则X²至少36。尾部每单位概率在平方总账中都至少贡献36，其他位置贡献又不会为负，这为限制尾部份额提供了依据。'],['用总平均约束份额','假设尾部概率为q，整个E(X²)至少为36q。本例均值0、方差4，所以36q≤4，得到q≤1/9；这是从非负账目推出来，不靠某条特定曲线。'],['读成保证而不是精确值','实际尾部概率可以远小于1/9，甚至为0。信息只有均值和方差时界通常较粗；若另知正态等分布条件，可以用更具体方法计算，但不能把额外信息凭空加入。']],
    '需要有限方差且阈值为正；上界可能很宽，若计算超过1可取概率基本上限1，不能当成精确尾概率。');
  put('prob-clt','为什么原数据歪着，平均数却可能像钟形？','看清中心极限定理研究的是标准化的和或平均，而非原始分布。',
    '单件等待时间可能很偏：多数短，偶尔很长。每次随机抽一批，算这一批平均；反复抽批会得到许多个“批平均”。在独立同分布且有限非零方差等条件下，把这些平均减中心、按平均自身的波动尺度缩放，会趋近标准正态。变化的是批平均的分布，不是原始每个等待值被魔法改成钟形。',
    [['中心极限定理','相应条件下，标准化的和或平均的分布趋近正态。','研究许多批平均的分布。'],['标准误 σ/√n','独立同分布时样本平均的标准差。','n翻四倍，平均的尺度减半。'],['标准化','平均减μ，再除以σ/√n。','Z＝(平均−μ)/(σ/√n)。']],
    'flow',[['每批抽n件','原数据可以偏斜'],['算每批平均','重复形成平均数分布'],['按标准误缩放','大样本时近似正态']],
    '经典独立同分布、均值μ和有限正方差σ²模型；n大不代表所有数据条件都自动成立。',
    [['先区分一件与一批','单件值X和一批平均是不同随机变量。重复抽样得到很多平均，才谈平均的抽样分布；不能看原数据直方图不像正态就直接否定该近似。'],['平均波动的单位更小','独立同分布时平均的方差为σ²/n，标准差为σ/√n。标准化分母用这个平均自身尺度，不是原单件的σ；样本量增大让平均通常更集中。'],['近似质量要看模型','经典定理给渐近趋势，不给所有问题统一的“三十个就一定够”。重尾、极端偏斜或相关数据会影响适用与精度，需要检查条件而非只看样本量标签。']],
    '这里讲经典版本，需有限非零方差等条件；相关或重尾情形要另论，渐近结论也不保证任意有限样本足够准确。');
  put('prob-binomial-normal','整数次数，怎样借连续曲线来近似？','用半格边界连接二项计数与正态面积。',
    '独立抛100次公平硬币，正面数K平均50、标准差5。近似“最多55次”时，可把55这一格看成54.5至55.5，累计到55.5接住整格，叫连续性修正。它对齐整数台阶与连续面积，却不能让任何小样本或极端成功率都成为好近似。',
    [['二项计数K','固定n次独立同成功率试验的成功数。','n＝100、p＝0.5。'],['正态近似','用中心np、方差np(1−p)的连续曲线近似计数。','中心50、标准差5。'],['连续性修正','用半个整数格调节连续面积边界。','K≤55对应累计到55.5。']],
    'flow',[['整数条件','K≤55'],['补上半格','连续阈值55.5'],['标准化','(55.5−50)/5＝1.1']],
    '公平独立100次二项模型，用正态近似包含整数55的整格质量，不是精确等式。',
    [['先写中心与波动','K服从n＝100、p＝0.5的二项模型，均值np＝50，方差np(1−p)＝25，所以标准差5。不能把方差25直接当标准化分母。'],['把含等号的整数格画完整','“最多55”包含55这一根概率柱。连续面积若只积到55，会截到这格中间；本例用55.5作边界，近似包含它的整格，再查对应标准正态累计。'],['最后判断近似是否值得信','成功与失败的期望次数都不能过小，尾部要求也会影响误差。本例较对称且次数多，直觉较合理；若只有少次试验或p极靠近0，优先考虑精确二项计算。']],
    '连续性修正是近似配准，不是恒等关系；近似精度依n、p及关注区域而变，不存在适合所有问题的机械阈值。');
  window.PLAIN_BEGINNER = Object.assign(window.PLAIN_BEGINNER || {}, data);
})();
